      if (colNum === -1 && (n === 'n' || n === 'no' || n === 'num' || n === 'numero' || n === 'item' || n === '#' || n === 'ordem')) colNum = c;

      if (colFerramenta === -1 && (n === 'ferramenta' || n.includes('ferramenta'))) colFerramenta = c;

