      if (colPrazoInteressados === -1 && (n.includes('interessad') || n.includes('terceir'))) colPrazoInteressados = c;

      if (colPrazoMP === -1 && (n.includes('custos') || n.includes('ministerio') || n.includes('prazo mp') || /\bmp\b/.test(n))) colPrazoMP = c;

