  // Parser leve para strings serialize() do PHP (ex.: mc_arrDadosEventoEncadeado)
  function parsePhpSerializedAssoc(rawStr) {
    if (!rawStr || typeof rawStr !== 'string') return {};
    let str = rawStr.trim();
    if (/^[aibdsN](?:%3A|:)/.test(str) && str.includes('%')) {
      str = decodificarComponenteQuerySeguro(str);
    }
    let pos = 0;
    const lerAte = (delim) => {
      const idx = str.indexOf(delim, pos);
      if (idx === -1) return '';
      const val = str.slice(pos, idx);
      pos = idx + delim.length;
      return val;
    };
    const lerValor = () => {
      if (pos >= str.length) return undefined;
      const tipo = str[pos++];
      if (tipo === 'N') {
        if (str[pos] === ';') pos++;
        return null;
      }
      if (tipo === 'b') {
        pos++; // ':'
        const v = lerAte(';');
        return v === '1';
      }
      if (tipo === 'i' || tipo === 'd') {
        pos++; // ':'
        const v = lerAte(';');
        return Number(v);
      }
      if (tipo === 's') {
        pos++; // ':'
        const len = parseInt(lerAte(':'), 10) || 0;
        if (str[pos] === '"') pos++;
        let val = '';
        if (str.slice(pos + len, pos + len + 2) === '";') {
          val = str.slice(pos, pos + len);
          pos += len + 2;
        } else {
          // Fallback para divergência entre bytes UTF-8 e code units JS
          const endM = str.indexOf('";', pos);
          if (endM !== -1) {
            val = str.slice(pos, endM);
            pos = endM + 2;
          } else {
            val = str.slice(pos, pos + len);
            pos += len + 2;
          }
        }
        return val;
      }
      if (tipo === 'a') {
        pos++; // ':'
        const count = parseInt(lerAte(':'), 10) || 0;
        if (str[pos] === '{') pos++;
        const obj = {};
        for (let i = 0; i < count && pos < str.length; i++) {
          if (str[pos] === '}') break;
          const k = lerValor();
          const v = lerValor();
          if (k !== undefined) obj[String(k)] = v;
        }
        if (str[pos] === '}') pos++;
        return obj;
      }
      return undefined;
    };
    const res = lerValor();
    return res && typeof res === 'object' ? res : {};
  }

  function parseTabelaFormularioPersonalizacaoListar(doc) {
    if (!doc) return [];
    const resultados = [];
    const idsVistos = new Set();

    const limpar = (s) => decodificarEntidadesHtml(decodeEntities((s || '').replace(/\s+/g, ' '))).trim();
    const encontrarIndiceCabecalho = (tbl) => {
      const idx = { desc: -1, padrao: -1, painel: -1, tipo: -1, grupo: -1 };
      if (!tbl) return idx;
      const ths = Array.from(tbl.querySelectorAll('tr th'));
      ths.forEach((th, i) => {
        const norm = normalizar(limpar(th.textContent));
        if (idx.desc === -1 && (norm.includes('descri') || norm === 'nome')) idx.desc = i;
        else if (idx.padrao === -1 && norm.includes('padrao')) idx.padrao = i;
        else if (idx.painel === -1 && norm.includes('painel')) idx.painel = i;
        else if (idx.tipo === -1 && norm.includes('tipo')) idx.tipo = i;
        else if (idx.grupo === -1 && norm.includes('grupo')) idx.grupo = i;
      });
      return idx;
    };

    const tabelas = Array.from(doc.querySelectorAll('table'));
    const tabelasComPrefs = tabelas.filter(t => {
      if (t.querySelector('input[name^="chkInfraItem"], input[id^="chkInfraItem"], a[onclick*="btnAlterarPreferenciaClick"], a[href*="id_preferencia="]')) return true;
      const ths = Array.from(t.querySelectorAll('th'));
      return ths.some(th => {
        const n = normalizar(limpar(th.textContent));
        return n.includes('descri') || n === 'nome';
      });
    });
    const alvos = tabelasComPrefs.length > 0 ? tabelasComPrefs : [doc];

    for (const container of alvos) {
      const idxCols = container.tagName === 'TABLE' ? encontrarIndiceCabecalho(container) : { desc: -1, padrao: -1, painel: -1, tipo: -1, grupo: -1 };
      const rows = Array.from(container.querySelectorAll('tr'));
      for (const tr of rows) {
        if (tr.querySelector('th') || tr.classList.contains('infraTrOrdenacao')) continue;
        const chk = tr.querySelector('input[name^="chkInfraItem"], input[id^="chkInfraItem"], input[type="checkbox"]:not([id*="SelecionarTodos"]):not([name*="SelecionarTodos"])');
        const tds = Array.from(tr.querySelectorAll('td'));
        if (!chk && tds.length < 2) continue;

        let linkEdit = tr.querySelector('a[href*="formulario_personalizacao"], a[onclick*="btnAlterarPreferenciaClick"], a[onclick*="Alterar"], a[title*="Alterar"], a[href*="id_preferencia="], a[href*="modal_edit_preferencia"]');
        let urlEditar = '';
        if (linkEdit) {
          const href = linkEdit.getAttribute('href') || '';
          const oncl = linkEdit.getAttribute('onclick') || '';
          const mClickUrl = oncl.match(/btnAlterarPreferenciaClick\(\s*['"][^'"]*['"]\s*,\s*['"]([^'"]+)['"]/i);
          const mGenUrl = oncl.match(/['"]([^'"]*controlador\.php\?[^'"]+)['"]/i);
          urlEditar = (mClickUrl && mClickUrl[1])
            ? mClickUrl[1]
            : ((mGenUrl && mGenUrl[1]) ? mGenUrl[1] : (href && !href.startsWith('#') && !href.startsWith('javascript:') ? href : ''));
        }
        if (!urlEditar && tr.innerHTML) {
          const mTrUrl = tr.innerHTML.match(/controlador\.php\?acao=(?:formulario_personalizacao_subfrm_salvar_consulta|ui_preferencias\/modal_edit_preferencia)[^'"]+/i);
          if (mTrUrl) urlEditar = mTrUrl[0];
        }

        let id = chk ? (chk.value || '').trim() : '';
        if (!id || /^(on|true|false)$/i.test(id)) id = '';
        if (!id && urlEditar) {
          const mIdUrl = urlEditar.match(/(?:id_preferencia|id_formulario_personalizacao|id)=([0-9a-zA-Z_-]+)/i);
          if (mIdUrl) id = mIdUrl[1];
        }
        if (!id && tr.innerHTML) {
          const mIdHtml = tr.innerHTML.match(/btnAlterarPreferenciaClick\(\s*['"]([0-9]+)['"]/i)
            || tr.innerHTML.match(/(?:id_preferencia|id_formulario_personalizacao)=(\d+)/i);
          if (mIdHtml) id = mIdHtml[1];
        }
        if (!id) {
          const attrId = (tr.getAttribute('data-id') || tr.getAttribute('id') || '').trim();
          if (/^\d+$/.test(attrId)) id = attrId;
        }
        if (!id || idsVistos.has(id)) continue;

        let nome = '';
        if (idxCols.desc !== -1 && tds[idxCols.desc]) {
          nome = limpar(tds[idxCols.desc].textContent);
        }
        if (!nome) {
          // Fallback: primeira célula não-vazia que não seja o checkbox nem ações
          const startCol = chk ? 1 : 0;
          for (let c = startCol; c < tds.length; c++) {
            const cand = limpar(tds[c].textContent);
            if (cand && !/^(sim|nao|unidade|individual|usu[aá]rio)$/i.test(normalizar(cand))) {
              nome = cand;
              break;
            }
          }
          if (!nome && tds[1]) nome = limpar(tds[1].textContent);
        }
        if (!nome) continue;

        const normSN = (v) => /^s$/i.test(v) ? 'Sim' : (/^n$/i.test(v) ? 'Não' : v);
        const padrao = normSN(idxCols.padrao !== -1 && tds[idxCols.padrao] ? limpar(tds[idxCols.padrao].textContent) : '');
        const painelInicial = normSN(idxCols.painel !== -1 && tds[idxCols.painel] ? limpar(tds[idxCols.painel].textContent) : '');
        const tipo = idxCols.tipo !== -1 && tds[idxCols.tipo] ? limpar(tds[idxCols.tipo].textContent) : '';
        const grupo = idxCols.grupo !== -1 && tds[idxCols.grupo] ? limpar(tds[idxCols.grupo].textContent) : '';

        idsVistos.add(id);
        resultados.push({
          id,
          nome,
          padrao: padrao || '',
          painelInicial: painelInicial || '',
          tipo: tipo || '',
          grupo: grupo || '',
          urlEditar: urlEditar ? urlEditar.replace(/&amp;/g, '&') : ''
        });
      }
    }
    return resultados;
  }

  function parseXmlPreferenciasAutoCompletar(xmlText) {
    const mapa = new Map();
    if (!xmlText || typeof xmlText !== 'string') return mapa;
    const dec = (s) => decodificarEntidadesHtml(decodeEntities(s || '')).trim();
    try {
      const xml = new DOMParser().parseFromString(xmlText, 'text/xml');
      xml.querySelectorAll('item').forEach(it => {
        const id = (it.getAttribute('id') || '').trim();
        const desc = dec(it.getAttribute('descricao') || it.textContent || '');
        const complemento = (it.getAttribute('complemento') || '').trim();
        if (id && desc) {
          mapa.set(id, { id, nome: desc, complemento });
        }
      });
    } catch (e) {}

    if (mapa.size === 0) {
      const reItem = /<item\b((?:[^>"']|"[^"]*"|'[^']*')*)\/?>/gi;
      let m;
      while ((m = reItem.exec(xmlText)) !== null) {
        const attrs = m[1];
        const mId = attrs.match(/\bid=["']([^"']+)["']/i);
        const mDesc = attrs.match(/\bdescricao=["']([^"']*)["']/i);
        const mComp = attrs.match(/\bcomplemento=["']([^"']*)["']/i);
        if (mId && mDesc && mDesc[1]) {
          const id = mId[1].trim();
          const nome = dec(mDesc[1]);
          const complemento = mComp ? mComp[1].trim() : '';
          if (id && nome) mapa.set(id, { id, nome, complemento });
        }
      }
    }
    return mapa;
  }

  function mesclarListaPreferenciasMinutas(itensTabela, mapaXml, itensMemoria) {
    const mapaFinal = new Map();
    const aplicarComplemento = (alvo, comp) => {
      if (!comp) return;
      alvo.complemento = alvo.complemento || comp;
      const parts = comp.split(';');
      if (!alvo.tipo && parts[0]) {
        alvo.tipo = parts[0] === 'U' ? 'Unidade' : (parts[0] === 'I' ? 'Individual' : alvo.tipo);
      }
      if (!alvo.padrao && parts[2]) {
        alvo.padrao = parts[2] === 'S' ? 'Sim' : (parts[2] === 'N' ? 'Não' : alvo.padrao);
      }
      if (!alvo.acaoPreferencial && parts[4]) {
        alvo.acaoPreferencial = parts[4] === 'S' ? 'Sim' : 'Não';
      }
    };

    for (const item of (itensTabela || [])) {
      const clone = { ...item };
      if (mapaXml && mapaXml.has(clone.id)) {
        aplicarComplemento(clone, mapaXml.get(clone.id).complemento);
      }
      mapaFinal.set(clone.id, clone);
    }

    if (mapaXml) {
      for (const [id, info] of mapaXml.entries()) {
        if (!mapaFinal.has(id)) {
          const novo = {
            id,
            nome: info.nome,
            padrao: '',
            painelInicial: '',
            tipo: '',
            grupo: '',
            complemento: info.complemento || '',
            urlEditar: ''
          };
          aplicarComplemento(novo, info.complemento);
          mapaFinal.set(id, novo);
        } else {
          aplicarComplemento(mapaFinal.get(id), info.complemento);
        }
      }
    }

    if (Array.isArray(itensMemoria)) {
      for (const it of itensMemoria) {
        const id = String(it.id || '').trim();
        const nome = decodificarEntidadesHtml(decodeEntities(String(it.descricao || it.text || it.value || ''))).trim();
        if (!id || !nome) continue;
        if (!mapaFinal.has(id)) {
          const novo = {
            id,
            nome,
            padrao: '',
            painelInicial: '',
            tipo: '',
            grupo: '',
            complemento: String(it.complemento || '').trim(),
            urlEditar: ''
          };
          aplicarComplemento(novo, novo.complemento);
          mapaFinal.set(id, novo);
        } else {
          aplicarComplemento(mapaFinal.get(id), String(it.complemento || '').trim());
        }
      }
    }

    return Array.from(mapaFinal.values());
  }

  function extrairUrlsAjaxTelaEproc(html, doc, baseHref, opcoes = {}) {
    const nomeAcao = opcoes.nomeAcao || 'minuta_cadastrar';
    const abs = (u) => {
      if (!u) return '';
      const clean = String(u).replace(/\\\//g, '/').replace(/&amp;/g, '&').trim();
      try {
        return new URL(clean, baseHref || 'https://eproc2g.tjsp.jus.br/eproc/').href;
      } catch (e) {
        return clean;
      }
    };

    let urlListar = '';
    if (doc) {
      const btn = doc.getElementById('listaPreferencias')
        || doc.getElementById('selPreferencia-list')
        || doc.querySelector('[onclick*="formulario_personalizacao_listar"], [data-url*="ui_preferencias"]');
      if (btn) {
        const oncl = btn.getAttribute('onclick') || '';
        const m = oncl.match(/exibirSubFrm\(\s*['"]([^'"]+)['"]/) || oncl.match(/['"]([^'"]*controlador\.php\?[^'"]*(?:formulario_personalizacao_listar|ui_preferencias)[^'"]*)['"]/i);
        urlListar = (m && m[1]) ? m[1] : (btn.getAttribute('data-url') || btn.getAttribute('href') || '');
      }
    }
    if (!urlListar && html) {
      const reListarAcao = new RegExp(`['"](controlador\\.php\\?[^'"]*acao=formulario_personalizacao_listar[^'"]*${nomeAcao}[^'"]*)['"]`, 'i');
      const m = html.match(reListarAcao)
        || html.match(/['"](controlador\.php\?[^'"]*acao=formulario_personalizacao_listar[^'"]*)['"]/i)
        || html.match(/['"](controlador\.php\?[^'"]*acao=ui_preferencias(?:\/|\\\/)modal_lista_preferencias[^'"]*)['"]/i);
      if (m && m[1]) urlListar = m[1];
    }

    let urlAutoComp = '';
    if (typeof window !== 'undefined' && doc === (typeof document !== 'undefined' ? document : null) && window.objAjaxAutoCompPreferencia) {
      const targetMem = window.objAjaxAutoCompPreferencia.ajaxTarget || window.objAjaxAutoCompPreferencia.urlServico || '';
      if (!nomeAcao || targetMem.includes(nomeAcao) || nomeAcao === 'minuta_cadastrar') {
        urlAutoComp = targetMem;
      }
    }
    if (!urlAutoComp && html) {
      const reAutoAcao = new RegExp(`['"](controlador_ajax\\.php\\?[^'"]*acao_ajax=preferencia_auto_completar[^'"]*${nomeAcao}[^'"]*)['"]`, 'i');
      const m = html.match(reAutoAcao)
        || html.match(/['"](controlador_ajax\.php\?[^'"]*acao_ajax=preferencia_auto_completar[^'"]+)['"]/i);
      if (m && m[1]) urlAutoComp = m[1];
    }

    let urlPrepararMov = extrairLiteralJsString(html, 'mc_link_preparar_movimentacao');
    if (!urlPrepararMov && html) {
      const m = html.match(/['"](controlador_ajax\.php\?acao_ajax=preparar_movimentacao[^'"]*)['"]/i);
      if (m && m[1]) urlPrepararMov = m[1];
    }

    let urlEncadearEvento = '';
    if (html) {
      const m = html.match(/['"](controlador_ajax\.php\?[^'"]*acao_ajax=encadear_evento[^'"]*)['"]/i);
      if (m && m[1]) urlEncadearEvento = m[1];
    }

    let urlEventosComp = '';
    if (html) {
      const m = html.match(/['"](controlador_ajax\.php\?acao_ajax=lista_eventos_complementares[^'"]*)['"]/i);
      if (m && m[1]) urlEventosComp = m[1];
    }

    let urlListarClassif = extrairLiteralJsString(html, 'mc_strLink');
    if ((!urlListarClassif || !urlListarClassif.includes('classificacao_conteudo_listar')) && html) {
      const m = html.match(/['"](controlador\.php\?acao=classificacao_conteudo_listar[^'"]*)['"]/i);
      if (m && m[1]) urlListarClassif = m[1];
    }

    const buscarUrlScriptOuHtml = (re) => {
      if (doc && typeof doc.querySelectorAll === 'function') {
        const scripts = doc.querySelectorAll('script');
        for (const s of scripts) {
          const txt = s.textContent || '';
          const m = txt.match(re);
          if (m && m[1]) return m[1];
        }
      }
      if (html) {
        const m = html.match(re);
        if (m && m[1]) return m[1];
      }
      return '';
    };

    const urlUiPrefListar = buscarUrlScriptOuHtml(/['"]([^'"]*ui_preferencias(?:\/|\\\/)listar(?=[&'"\s\\])[^'"]*)['"]/i)
      || buscarUrlScriptOuHtml(/['"]([^'"]*ui_preferencias(?:\/|\\\/)listar[^'"]*)['"]/i);
    const urlBuscarRequest = buscarUrlScriptOuHtml(/['"]([^'"]*ui_preferencias(?:\/|\\\/)buscar_request_por_id[^'"]*)['"]/i);
    const urlListarLocRelatorio = buscarUrlScriptOuHtml(/['"]([^'"]*relatorio_geral(?:\/|\\\/)listar_localizador_orgao[^'"]*)['"]/i);

    const buscarUrlMenu = (acao) => {
      if (doc && typeof doc.querySelector === 'function') {
        const links = doc.querySelectorAll(`a[href*="acao=${acao}"]`);
        for (const a of links) {
          const href = (a.getAttribute('href') || '').replace(/&amp;/gi, '&');
          if (new RegExp(`[?&]acao=${acao}(?:&|$)`, 'i').test(href)) return href;
        }
      }
      if (html) {
        const re = new RegExp(`["']([^"']*controlador\\.php\\?[^"']*acao=${acao}(?:&|&amp;)[^"']*|[^"']*controlador\\.php\\?[^"']*acao=${acao})["']`, 'i');
        const m = html.match(re);
        if (m && m[1]) return m[1];
      }
      if (typeof obterUrlAcaoMenu === 'function' && (!doc || doc === (typeof document !== 'undefined' ? document : null))) {
        try { return obterUrlAcaoMenu(acao) || ''; } catch (e) {}
      }
      return '';
    };

    return {
      urlListar: abs(urlListar),
      urlAutoComp: abs(urlAutoComp),
      urlPrepararMov: abs(urlPrepararMov),
      urlEncadearEvento: abs(urlEncadearEvento),
      urlEventosComp: abs(urlEventosComp),
      urlListarClassif: abs(urlListarClassif),
      urlUiPrefListar: abs(urlUiPrefListar),
      urlBuscarRequest: abs(urlBuscarRequest),
      urlListarLocRelatorio: abs(urlListarLocRelatorio),
      urlMinutaAreaTrabalho: abs(buscarUrlMenu('minuta_area_trabalho')),
      urlAutomatizarLoc: abs(buscarUrlMenu('automatizar_localizadores')),
      urlLocalizadoresOrgao: abs(buscarUrlMenu('localizador_orgao_listar'))
    };
  }

  function extrairUrlsAjaxNovaMinuta(html, doc, baseHref) {
    return extrairUrlsAjaxTelaEproc(html, doc, baseHref, { nomeAcao: 'minuta_cadastrar' });
  }

  function construirMapaSelectOptions(doc, selectId) {
    const mapa = new Map();
    if (!doc) return mapa;
    const sel = doc.getElementById(selectId);
    if (!sel) return mapa;
    sel.querySelectorAll('option').forEach(opt => {
      const val = (opt.value || opt.getAttribute('value') || '').trim();
      const txt = decodificarEntidadesHtml(decodeEntities(opt.textContent || '')).replace(/\s+/g, ' ').trim();
      if (val && val !== 'null' && txt && !/^\[?\s*(desmarcar|selecione)/i.test(txt)) {
        mapa.set(val, txt);
      }
    });
    return mapa;
  }

  function obterValoresSelecionadosSelect(doc, selectId) {
    if (!doc) return [];
    const sel = doc.getElementById(selectId);
    if (!sel) return [];
    const out = [];
    sel.querySelectorAll('option').forEach(opt => {
      if (opt.selected || opt.hasAttribute('selected')) {
        const val = (opt.value || opt.getAttribute('value') || '').trim();
        if (val && val !== 'null') out.push(val);
      }
    });
    return out;
  }

  function mesclarMapasStrings(mapaPrimario, mapaSecundario) {
    const out = new Map();
    const aplicar = (m) => {
      if (!m) return;
      if (m instanceof Map) {
        for (const [k, v] of m.entries()) {
          if (v) out.set(String(k), String(v));
        }
      } else if (Array.isArray(m)) {
        for (const item of m) {
          if (Array.isArray(item) && item.length >= 2) {
            if (item[1]) out.set(String(item[0]), String(item[1]));
          }
        }
      } else if (typeof m === 'object') {
        for (const [k, v] of Object.entries(m)) {
          if (v) out.set(String(k), String(v));
        }
      }
    };
    aplicar(mapaSecundario);
    aplicar(mapaPrimario);
    return out;
  }

  function obterMapaNomeLocalizadoresGlobal(docExtra = null, htmlExtra = '') {
    if (typeof window === 'undefined') return new Map();
    if (!window._eprocCacheNomeLocalizadores) {
      window._eprocCacheNomeLocalizadores = new Map();
    }
    const mapaCache = window._eprocCacheNomeLocalizadores;

    const processarObjeto = (obj) => {
      if (!obj || typeof obj !== 'object') return;
      for (const [id, dados] of Object.entries(obj)) {
        const idLimpo = String(id || '').trim();
        if (!idLimpo || idLimpo === 'null') continue;
        const rot = Array.isArray(dados) ? dados[0] : (typeof dados === 'string' ? dados : (dados && (dados.name || dados.descricao)));
        if (rot) {
          const nomeDec = decodificarEntidadesHtml(decodeEntities(String(rot))).replace(/\u00a0/g, ' ').replace(/\s+/g, ' ').trim();
          if (nomeDec && !mapaCache.has(idLimpo)) mapaCache.set(idLimpo, nomeDec);
        }
      }
    };

    const processarTexto = (texto) => {
      if (!texto || typeof texto !== 'string' || !texto.includes('nomeLocalizadores')) return;
      const m = texto.match(/var\s+nomeLocalizadores\s*=\s*(\{[\s\S]*?\});/);
      if (m) {
        try { processarObjeto(JSON.parse(m[1])); } catch (eJ) {}
      }
      const regexEntry = /"(\d{15,35})"\s*:\s*\[\s*"((?:\\.|[^"\\])*)"/g;
      let mE;
      while ((mE = regexEntry.exec(texto)) !== null) {
        const id = mE[1];
        let rot = mE[2];
        try {
          rot = JSON.parse(`"${rot}"`);
        } catch (e) {
          rot = rot.replace(/\\u([0-9a-fA-F]{4})/g, (_, h) => String.fromCharCode(parseInt(h, 16)));
        }
        if (id && rot && !mapaCache.has(id)) {
          const nomeDec = decodificarEntidadesHtml(decodeEntities(rot)).replace(/\u00a0/g, ' ').replace(/\s+/g, ' ').trim();
          if (nomeDec) mapaCache.set(id, nomeDec);
        }
      }
    };

    const processarDoc = (d) => {
      if (!d) return;
      try {
        const scripts = d.querySelectorAll ? d.querySelectorAll('script') : [];
        for (const s of scripts) {
          if (s.textContent && s.textContent.includes('nomeLocalizadores')) {
            processarTexto(s.textContent);
          }
        }
      } catch (e) {}
      try {
        ['selNovoLocalizador', 'selLocalizadorSecundario', 'selLocalizadorDesativar', 'selLocalizador', 'selLocalizadores'].forEach(sid => {
          const sEl = d.getElementById ? d.getElementById(sid) : null;
          if (sEl && sEl.options) {
            Array.from(sEl.options).forEach(o => {
              const id = String(o.value || '').trim();
              const txt = (o.textContent || '').trim();
              if (id && id !== 'null' && txt && !/^\[?\s*(desmarcar|selecione)/i.test(txt) && !mapaCache.has(id)) {
                mapaCache.set(id, decodificarEntidadesHtml(decodeEntities(txt)).replace(/\u00a0/g, ' ').replace(/\s+/g, ' ').trim());
              }
            });
          }
        });
      } catch (e) {}
    };

    if (typeof window !== 'undefined' && window.nomeLocalizadores) {
      processarObjeto(window.nomeLocalizadores);
    }
    if (typeof document !== 'undefined') {
      processarDoc(document);
    }
    if (docExtra && docExtra !== (typeof document !== 'undefined' ? document : null)) {
      processarDoc(docExtra);
    }
    if (htmlExtra) {
      processarTexto(htmlExtra);
    }

    return mapaCache;
  }

  function resolverIdsParaTextos(ids, mapaOpcoes) {
    const limpos = [];
    const vistos = new Set();
    const cacheViewer = (typeof obterCacheCatalogosMinutaViewer === 'function') ? obterCacheCatalogosMinutaViewer() : null;
    const mapaExtra = (cacheViewer && cacheViewer.localizadoresExtra) || null;
    const mapaGlobal = (typeof obterMapaNomeLocalizadoresGlobal === 'function') ? obterMapaNomeLocalizadoresGlobal() : null;

    for (const rawId of (ids || [])) {
      const id = String(rawId || '').trim();
      if (!id || id === 'null' || id === 'undefined' || vistos.has(id)) continue;
      vistos.add(id);
      let nome = (mapaOpcoes && mapaOpcoes.get(id))
        || (mapaExtra && mapaExtra.get(id))
        || (mapaGlobal && mapaGlobal.get(id))
        || '';

      if (!nome && typeof window !== 'undefined' && window.nomeLocalizadores && window.nomeLocalizadores[id]) {
        const d = window.nomeLocalizadores[id];
        nome = Array.isArray(d) ? d[0] : (typeof d === 'string' ? d : (d.name || d.descricao || ''));
        if (nome) nome = decodificarEntidadesHtml(decodeEntities(nome)).trim();
      }

      if (!nome && typeof document !== 'undefined' && typeof document.getElementById === 'function') {
        const selects = ['selNovoLocalizador', 'selLocalizadorDesativar', 'selLocalizadorSecundario', 'selLocalizador', 'selLocalizadores'];
        for (const sid of selects) {
          const sEl = document.getElementById(sid);
          if (sEl && sEl.options) {
            const opt = Array.from(sEl.options).find(o => String(o.value || '').trim() === id);
            if (opt && opt.textContent && !/^\[?\s*(desmarcar|selecione)/i.test(opt.textContent)) {
              nome = decodificarEntidadesHtml(decodeEntities(opt.textContent)).replace(/\s+/g, ' ').trim();
              break;
            }
          }
        }
      }

      limpos.push(nome || `ID: ${id}`);
    }
    return limpos;
  }

  function extrairCamposBaseFormEproc(doc, baseHref, htmlBase = '', opcoes = {}) {
    if (!doc) return null;
    const formId = opcoes.formId || 'frmMinutaCadastro';
    const acaoPattern = opcoes.acaoPattern || 'minuta_cadastrar';
    const form = doc.getElementById(formId) || doc.querySelector(`form[action*="${acaoPattern}"]`);
    if (!form) return null;

    const rawAction = form.getAttribute('action') || (baseHref || '');
    const actionUrl = rawAction
      ? new URL(rawAction.replace(/&amp;/g, '&'), baseHref || 'https://eproc2g.tjsp.jus.br/eproc/').href
      : (baseHref || '');

    const basePairs = [];
    const camposIgnorar = new Set([
      'hdnNumIdValorSelecionadoCombo',
      'isChangePreferencia',
      'hdnStrDescricaoPreferencia',
      'hdnStrPreferenciaUsuario',
      'hdnAcaoPreferencia',
      'hdnPreferencia',
      'txtPreferencia',
      'hdnPreferenciaUsuario',
      'txtDescricaoCadastro',
      'selClassificacaoConteudoIds',
      'hdnDadosComplementares',
      'hdnDadosAutuacao',
      'hdnEvento',
      'hdnEventoCitacaoIntimacao',
      'hdnIdModelo',
      'hdnTxtModelo',
      'hdnIdModeloPadrao',
      'hdnModeloPadrao',
      'hdnIdDocumentoBase',
      'hdnTextoPadrao1',
      'hdnTextoPadrao2',
      'hdnTextoPadrao3',
      'hdnCodStatusMinuta',
      'hdnSinAssinaturaRestritaMagistrado',
      'hdnAgendamentoAudiencia',
      'hdnSelEventoAudiencia',
      'hdnConsultaNormal',
      'solr_forcar_pesquisa',
      'hdnExcel',
      'hdnOrigemExterna',
      'hdnNumChavePesquisaMinuta',
      'hdnNumChavePesquisaDocumento',
      'hdnInfraSelecoes'
    ]);

    form.querySelectorAll('input[type="hidden"]').forEach(inp => {
      const name = (inp.name || inp.getAttribute('name') || '').trim();
      if (!name || camposIgnorar.has(name) || name.startsWith('selLocalizadorPrincipal_value')) return;
      basePairs.push([name, inp.value || inp.getAttribute('value') || '']);
    });

    const getFieldVal = (id, def = '') => {
      const el = doc.getElementById(id);
      return el ? (el.value || el.getAttribute('value') || def) : def;
    };

    const mProcUrl = (baseHref || '').match(/[?&](?:num_processo|txtNumProcesso)=([^&]+)/i);
    const numProcesso = getFieldVal('numProcesso', '')
      || getFieldVal('hdnNumProcessoLista', '')
      || getFieldVal('hdnTxtNumProcesso', '')
      || getFieldVal('hdnNumProcesso', '')
      || (htmlBase ? extrairLiteralJsString(htmlBase, 'mc_numProcesso') : '')
      || (mProcUrl && mProcUrl[1] ? decodeURIComponent(mProcUrl[1]).trim() : '');

    const catalogosBasicos = {
      localizadores: mesclarMapasStrings(
        construirMapaSelectOptions(doc, 'selNovoLocalizador'),
        mesclarMapasStrings(
          construirMapaSelectOptions(doc, 'selLocalizadorSecundario'),
          mesclarMapasStrings(
            construirMapaSelectOptions(doc, 'selLocalizadorDesativar'),
            construirMapaSelectOptions(doc, 'selLocalizador')
          )
        )
      ),
      comportamentos: construirMapaSelectOptions(doc, 'selOpcaoLocalizador'),
      grupos: mesclarMapasStrings(
        construirMapaSelectOptions(doc, 'selFormularioPersonalizacaoGrupo'),
        construirMapaSelectOptions(doc, 'Grupo')
      ),
      assinantes: construirMapaSelectOptions(doc, 'selAssinante'),
      tratamentos: construirMapaSelectOptions(doc, 'selTratamento'),
      sigilos: mesclarMapasStrings(
        construirMapaSelectOptions(doc, 'selSigilo'),
        construirMapaSelectOptions(doc, 'selIdSigilo_Padrao')
      ),
      statusMinuta: construirMapaSelectOptions(doc, 'selStatusMinuta')
    };

    if (Array.isArray(opcoes.selectsExtras)) {
      opcoes.selectsExtras.forEach(sid => {
        catalogosBasicos[sid] = construirMapaSelectOptions(doc, sid);
      });
    }

    return {
      actionUrl,
      basePairs,
      numProcesso,
      catalogosBasicos
    };
  }

  function extrairCamposBaseFormMinuta(doc, baseHref, htmlBase = '') {
    return extrairCamposBaseFormEproc(doc, baseHref, htmlBase, {
      formId: 'frmMinutaCadastro',
      acaoPattern: 'minuta_cadastrar'
    });
  }

  function formatarPrazosIntimacaoMinuta(agQuery, arrPrefIntimacao, camposP = null) {
    const lerCampo = (key) => {
      if (agQuery && agQuery.get(key)) return String(agQuery.get(key)).trim();
      if (Array.isArray(arrPrefIntimacao)) {
        for (const bloco of arrPrefIntimacao) {
          const hit = (bloco.arrDados || []).find(d => d.key === key && d.value);
          if (hit) return String(hit.value).trim();
        }
      }
      if (camposP && camposP[key] !== undefined && camposP[key] !== null) {
        const s = String(camposP[key]).trim();
        if (s && s !== 'null' && s !== 'N') return s;
      }
      return '';
    };

    let opAvancada = lerCampo('opcoes_avancadas');
    if (!opAvancada && Array.isArray(arrPrefIntimacao) && arrPrefIntimacao[0] && arrPrefIntimacao[0].evento) {
      opAvancada = arrPrefIntimacao[0].evento.opAvancada || '';
    }

    const camposPrazo = [
      ['txtPrazoTodos', 'Todos'],
      ['txtPrazoIgual', 'Igual'],
      ['txtPrazoTodosPolo', 'Todos polos'],
      ['txtPrazoEntPrazoEspecial', 'Ent. Pz Especial'],
      ['txtPrazoEntPrazoSimples', 'Ent. Pz Simples'],
      ['txtPrazoEntQQPrazo', 'Ent. Qq Prazo'],
      ['txtPrazoNaoEntPrazoSimples', 'Demais Pz Simples'],
      ['txtPrazoDPU', 'DPU'],
      ['txtPrazoPeritosECia', 'Peritos/Aux.'],
      ['txtPrazoPeritosECiaPolo', 'Peritos/Aux. (Polo)'],
      ['txtPrazoAPS_CEF', 'APS/CEF'],
      ['txtPrazoAPS_CEFPolo', 'APS/CEF (Polo)'],
      ['txtPrazoAutores', 'Autores'],
      ['txtPrazoReus', 'Réus'],
      ['txtPrazoInteressados', 'Interessados'],
      ['txtPrazoMPF', 'MPF'],
      ['txtPrazoOutros', 'Outros']
    ];

    const partes = [];
    for (const [k, label] of camposPrazo) {
      const val = lerCampo(k);
      if (val && val !== 'null') {
        const suf = /^\d+$/.test(val) ? 'd' : '';
        partes.push(`${label}: ${val}${suf}`);
      }
    }

    let temUrgente = false;
    const chksUrgente = [
      'chkIntimacaoUrgente',
      'chkSelPrazoIntimacaoUrgenteTodos', 'chkSelIntimacaoUrgenteTodos',
      'chkSelPrazoIntimacaoUrgenteAutores', 'chkSelPrazoIntimacaoUrgenteReus',
      'chkSelPrazoIntimacaoUrgenteInteressados', 'chkSelPrazoIntimacaoUrgenteMPF',
      'chkSelParteIntimacaoUrgenteEntPrazoEspecial', 'chkSelParteIntimacaoUrgenteEntPrazoSimples',
      'chkSelParteIntimacaoUrgenteNaoEntPrazoSimples', 'chkSelParteIntimacaoUrgenteDPU'
    ];
    for (const kUrg of chksUrgente) {
      const vUrg = lerCampo(kUrg);
      if (vUrg === 'S' || vUrg === 'on' || vUrg === '1' || vUrg === 'true') {
        temUrgente = true;
        break;
      }
    }
    if (!temUrgente && agQuery) {
      for (const [k, v] of agQuery.entries()) {
        if (/Urgente/i.test(k) && (v === 'S' || v === 'on' || v === '1' || v === 'true')) {
          temUrgente = true;
          break;
        }
      }
    }
    if (temUrgente) partes.push('Urgente');

    const mapOpcoes = {
      igual: 'Mesmo prazo',
      porEntidade: 'Por entidade',
      porPolo: 'Por polo',
      porTipoDeParte: 'Por tipo de parte',
      porTipoParte: 'Por tipo de parte',
      porParte: 'Por parte'
    };

    const modoLabel = opAvancada ? (mapOpcoes[opAvancada] || opAvancada) : '';
    if (partes.length === 0) return modoLabel || '';
    return modoLabel ? `${modoLabel} (${partes.join(' | ')})` : partes.join(' | ');
  }

  function parseRegistrosDadosComplementaresCodificados(bruto) {
    if (!bruto || typeof bruto !== 'string') return [];
    const limpo = decodificarComponenteQuerySeguro(bruto).trim();
    if (!limpo || !limpo.includes('±')) return [];
    const out = [];
    for (const seg of limpo.split(';')) {
      const s = seg.trim();
      if (!s) continue;
      const partes = s.split('±').map(p => p.trim());
      if (partes.length >= 2 && (partes[0] || partes[1] || partes[2])) {
        out.push({
          idCampo: partes[0] || '',
          idValor: partes[1] || '',
          extra: partes.slice(2).filter(Boolean).join(' ')
        });
      }
    }
    return out;
  }

  function resolverCampoCatalogoDadosComp(mapasSel, keyOrId) {
    if (!mapasSel || !(mapasSel instanceof Map) || !keyOrId) return null;
    const raw = String(keyOrId).replace(/\[\]$/, '').trim();
    if (mapasSel.has(raw)) return mapasSel.get(raw);
    const digits = raw.match(/(\d+)$/);
    if (digits) {
      const suf = digits[1];
      for (const [k, info] of mapasSel.entries()) {
        if (k === suf || new RegExp(`(?:^|\\D)${suf}$`).test(k)) return info;
      }
    }
    return null;
  }

  function formatarDadosComplementaresMinuta(rawMcStr, agQuery, catalogos) {
    const blocos = [];
    const textosVistos = new Set();
    const adicionar = (t) => {
      const s = decodificarEntidadesHtml(decodeEntities(String(t || ''))).replace(/\s+/g, ' ').trim();
      if (s && !textosVistos.has(s)) {
        textosVistos.add(s);
        blocos.push(s);
      }
    };

    if (catalogos && catalogos.descDadosDom) {
      adicionar(catalogos.descDadosDom);
    }
    if (catalogos && catalogos.descDadosPrepMov) {
      adicionar(catalogos.descDadosPrepMov);
    }

    const catGlobal = (catalogos && catalogos.dadosCompCatalogo) || null;
    const mapasSel = (catalogos && catalogos.dadosCompSelects) || new Map();
    if (blocos.length === 0 && agQuery) {
      for (const [k, vals] of agQuery.entries()) {
        if (/^(sel|txt|chk|rdo)DadoComplementar/i.test(k)) {
          const validos = vals.filter(v => v && v !== 'null');
          if (validos.length === 0) continue;
          const info = resolverCampoCatalogoDadosComp(mapasSel, k);
          if (info && info.options && info.options.size > 0) {
            const nomes = validos.map(v => info.options.get(v) || v);
            adicionar(`${info.label || k}: ${nomes.join(', ')}`);
          } else {
            adicionar(`${k.replace(/\[\]$/, '')}: ${validos.join(', ')}`);
          }
        }
      }
    }

    const bruto = rawMcStr || (agQuery ? agQuery.get('hdnDadosComplementares') : '') || '';
    if (blocos.length === 0 && bruto && bruto.trim()) {
      const registros = parseRegistrosDadosComplementaresCodificados(bruto);
      if (registros.length > 0) {
        for (const reg of registros) {
          const chavePar = `${reg.idCampo}|${reg.idValor}`;
          const textoPar = catGlobal && catGlobal.pares && catGlobal.pares.get(chavePar);
          if (textoPar) {
            const sufixo = (reg.extra && !textoPar.includes(reg.extra)) ? ` (${reg.extra})` : '';
            adicionar(`${textoPar}${sufixo}`);
            continue;
          }

          const infoGlobal = catGlobal && catGlobal.campos && catGlobal.campos.get(reg.idCampo);
          const info = resolverCampoCatalogoDadosComp(mapasSel, reg.idCampo) || infoGlobal || null;
          const nomeCampo = (info && info.label) ? info.label : `Dado #${reg.idCampo || '?'}`;
          const valorBruto = reg.idValor || reg.extra || '';
          const nomeValor = (info && info.options && info.options.get(reg.idValor))
            ? info.options.get(reg.idValor)
            : (valorBruto ? (info && info.options ? valorBruto : (reg.extra || `Valor #${reg.idValor}`)) : '');
          adicionar(nomeValor ? `${nomeCampo}: ${nomeValor}${reg.extra && nomeValor !== reg.extra ? ` (${reg.extra})` : ''}` : nomeCampo);
        }
      } else {
        adicionar(decodificarComponenteQuerySeguro(bruto));
      }
    }

    return blocos.join(' | ');
  }

  function extrairModeloECodigo(modeloTexto, camposP, mcModeloCod) {
    const texto = (modeloTexto || '').trim();
    let cod = (mcModeloCod || '').trim();
    if (!cod && camposP && camposP.ModeloPadrao) {
      cod = String(camposP.ModeloPadrao).split(';')[0].trim();
    }
    if (!cod && texto) {
      const mTraço = texto.match(/-\s*(\d{8,})\s*$/) || texto.match(/\(m(\d+)\)/i);
      if (mTraço) cod = mTraço[1];
    }
    let nomeLimpo = texto;
    if (cod && nomeLimpo) {
      nomeLimpo = nomeLimpo.replace(new RegExp(`\\s*-\\s*${cod.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\s*$`), '').trim();
      nomeLimpo = nomeLimpo.replace(/\s*-\s*\d{8,}\s*$/, '').trim();
      nomeLimpo = nomeLimpo.replace(/\s*\(m\d+\)\s*$/i, '').trim();
    }
    return { modeloNome: nomeLimpo || texto, modeloCod: cod };
  }

  function extrairItensSelect2OuIds(valorBruto, mapaDestino) {
    if (valorBruto === null || valorBruto === undefined) return [];
    const ids = [];
    const registrarObj = (obj) => {
      if (!obj || typeof obj !== 'object') return;
      const id = obj.id !== undefined && obj.id !== null ? String(obj.id).trim() : '';
      const txtRaw = obj.text !== undefined && obj.text !== null ? String(obj.text) : (obj.descricao !== undefined ? String(obj.descricao) : '');
      const txt = decodificarEntidadesHtml(decodeEntities(txtRaw)).replace(/\s+/g, ' ').trim();
      if (id && id !== 'null') {
        ids.push(id);
        if (txt && mapaDestino instanceof Map && !mapaDestino.has(id)) {
          mapaDestino.set(id, txt);
        }
      }
    };

    if (Array.isArray(valorBruto)) {
      valorBruto.forEach(item => {
        if (item && typeof item === 'object') registrarObj(item);
        else {
          const s = String(item || '').trim();
          if (s && s !== 'null') ids.push(s);
        }
      });
      return ids;
    }

    const brutoStr = String(valorBruto).trim();
    if (!brutoStr || brutoStr === 'null') return [];

    if (/^\s*[\[{]/.test(brutoStr) || brutoStr.includes('{')) {
      let parseOk = false;
      try {
        const parsed = JSON.parse(brutoStr);
        (Array.isArray(parsed) ? parsed : [parsed]).forEach(registrarObj);
        parseOk = true;
      } catch (e) {}

      if (!parseOk) {
        const blocos = brutoStr.match(/\{[^{}]*\}/g) || [];
        for (const bloco of blocos) {
          const mId = bloco.match(/['"]id['"]\s*:\s*(['"])([\s\S]*?)\1/i);
          const mTxt = bloco.match(/['"](?:text|descricao)['"]\s*:\s*(['"])([\s\S]*?)\1/i);
          if (mId && mId[2]) {
            registrarObj({ id: mId[2], text: mTxt ? mTxt[2] : '' });
            parseOk = true;
          }
        }
      }
      if (parseOk || brutoStr.includes('{')) return ids;
    }

    return brutoStr.split(',').map(s => s.trim()).filter(s => s && s !== 'null');
  }

  function parseDetalhesPreferenciaMinutaHtml(htmlResp, prefItem, ctxBase, catalogosExtras = {}) {
    const html = htmlResp || '';
    const docResp = new DOMParser().parseFromString(html, 'text/html');
    const baseCat = (ctxBase && (ctxBase.catalogosBasicos || (ctxBase.formInfo && ctxBase.formInfo.catalogosBasicos))) || {};

    const camposP = extrairObjetoJsJson(html, 'camposPersonalizadosOrdem') || {};
    let rawAgendamento = '';
    if (camposP.Agendamento) {
      const agVal = String(camposP.Agendamento).trim();
      if (agVal.startsWith('url_') || (agVal.includes('&') && agVal.includes('='))) {
        rawAgendamento = decodificarComponenteQuerySeguro(agVal);
      } else {
        rawAgendamento = decodificarBase64QuerySeguro(agVal) || decodificarComponenteQuerySeguro(agVal);
      }
    } else if (camposP.frmDadosMinutaParaATP) {
      rawAgendamento = decodificarBase64QuerySeguro(camposP.frmDadosMinutaParaATP);
    }
    const agQuery = parseQueryStringSegura(rawAgendamento);

    // Catálogos combinados (DOM retornado tem prioridade; DOM vivo da página; baseline como apoio; caches AJAX por último)
    const mapaLocsDomVivo = new Map();
    const mapaGlobalLocs = (typeof obterMapaNomeLocalizadoresGlobal === 'function')
      ? obterMapaNomeLocalizadoresGlobal(docResp, html)
      : new Map();
    mapaGlobalLocs.forEach((v, k) => { if (!mapaLocsDomVivo.has(k)) mapaLocsDomVivo.set(k, v); });

    if (typeof document !== 'undefined') {
      ['selNovoLocalizador', 'selLocalizadorSecundario', 'selLocalizadorDesativar', 'selLocalizador', 'selLocalizadores'].forEach(sid => {
        const subM = construirMapaSelectOptions(document, sid);
        subM.forEach((v, k) => { if (!mapaLocsDomVivo.has(k)) mapaLocsDomVivo.set(k, v); });
      });
    }
    if (typeof window !== 'undefined' && window.nomeLocalizadores && typeof window.nomeLocalizadores === 'object') {
      Object.entries(window.nomeLocalizadores).forEach(([id, dados]) => {
        if (id && dados && !mapaLocsDomVivo.has(String(id))) {
          const rot = Array.isArray(dados) ? dados[0] : (typeof dados === 'string' ? dados : (dados.name || dados.descricao || ''));
          if (rot) mapaLocsDomVivo.set(String(id), decodificarEntidadesHtml(decodeEntities(rot)).trim());
        }
      });
    }

    const mapaLocs = mesclarMapasStrings(
      construirMapaSelectOptions(docResp, 'selNovoLocalizador'),
      mesclarMapasStrings(
        construirMapaSelectOptions(docResp, 'selLocalizadorSecundario'),
        mesclarMapasStrings(
          construirMapaSelectOptions(docResp, 'selLocalizadorDesativar'),
          mesclarMapasStrings(
            mapaLocsDomVivo,
            mesclarMapasStrings(catalogosExtras.localizadoresExtras, baseCat.localizadores)
          )
        )
      )
    );
    const mapaComport = mesclarMapasStrings(construirMapaSelectOptions(docResp, 'selOpcaoLocalizador'), baseCat.comportamentos);
    if (!mapaComport.has('0')) mapaComport.set('0', 'Remover o processo do(s) localizador(es) informado(s)');
    if (!mapaComport.has('1')) mapaComport.set('1', 'Remover o processo de TODOS localizadores');
    if (!mapaComport.has('2')) mapaComport.set('2', 'Remover o processo de TODOS localizadores, EXCETO os de sistema');
    if (!mapaComport.has('3')) mapaComport.set('3', 'NÃO remover o processo de localizador algum (apenas acrescentar o indicado)');
    if (!mapaComport.has('5')) mapaComport.set('5', 'Apenas substituir o localizador PRINCIPAL pelo indicado');

    const mapaGrupos = mesclarMapasStrings(construirMapaSelectOptions(docResp, 'selFormularioPersonalizacaoGrupo'), baseCat.grupos);
    const mapaAssinantes = mesclarMapasStrings(construirMapaSelectOptions(docResp, 'selAssinante'), baseCat.assinantes);
    const mapaTratamentos = mesclarMapasStrings(construirMapaSelectOptions(docResp, 'selTratamento'), baseCat.tratamentos);
    const mapaSigilos = mesclarMapasStrings(construirMapaSelectOptions(docResp, 'selSigilo'), baseCat.sigilos);
    const mapaStatus = mesclarMapasStrings(construirMapaSelectOptions(docResp, 'selStatusMinuta'), baseCat.statusMinuta);
    if (!mapaStatus.has('1')) mapaStatus.set('1', 'Rascunho');
    if (!mapaStatus.has('2')) mapaStatus.set('2', 'Para conferir');
    if (!mapaStatus.has('3')) mapaStatus.set('3', 'Conferida');
    if (!mapaStatus.has('4')) mapaStatus.set('4', 'Para assinar');

    // Metadados gerais da preferência
    const radioTipoChecked = docResp.querySelector('input[name="rdPrefTipo"][checked], input[name="rdPrefTipo"]:checked');
    const rawTipo = agQuery.get('rdPrefTipo') || (radioTipoChecked ? radioTipoChecked.value : '') || (prefItem.complemento ? prefItem.complemento.split(';')[0] : '');
    const tipo = rawTipo === 'U' ? 'Unidade' : (rawTipo === 'I' ? 'Individual' : (prefItem.tipo || ''));

    const padrao = prefItem.padrao || (prefItem.complemento && prefItem.complemento.split(';')[2] === 'S' ? 'Sim' : (prefItem.complemento && prefItem.complemento.split(';')[2] === 'N' ? 'Não' : ''));

    const grupoSelIds = obterValoresSelecionadosSelect(docResp, 'selFormularioPersonalizacaoGrupo');
    const grupoId = agQuery.get('selFormularioPersonalizacaoGrupo') || grupoSelIds[0] || '';
    const grupo = (grupoId && grupoId !== 'null' ? (mapaGrupos.get(grupoId) || '') : '') || prefItem.grupo || '';

    const chkMovPref = docResp.getElementById('chkMovPreferencial');
    const movPrefFlag = agQuery.get('chkMovPreferencial')
      || ((chkMovPref && (chkMovPref.checked || chkMovPref.hasAttribute('checked'))) ? 'S' : '')
      || (prefItem.complemento ? prefItem.complemento.split(';')[4] : '');
    const acaoPreferencial = movPrefFlag === 'S' ? 'Sim' : 'Não';

    // Localizadores
    const radioLocChecked = docResp.querySelector('input[name="rdPrefLocalizadores"][checked], input[name="rdPrefLocalizadores"]:checked');
    const rdLoc = agQuery.get('rdPrefLocalizadores')
      || extrairLiteralJsString(html, 'mc_strRdPrefLocalizadores')
      || (radioLocChecked ? radioLocChecked.value : '');
    const mapModoLoc = { L: 'Localizadores selecionados', M: 'Marcar todos atuais', D: 'Desmarcar todos atuais' };
    const modoLocalizadores = mapModoLoc[rdLoc] || rdLoc || '';

    const comportIds = obterValoresSelecionadosSelect(docResp, 'selOpcaoLocalizador');
    const comportCod = agQuery.get('selOpcaoLocalizador') !== null ? agQuery.get('selOpcaoLocalizador') : (comportIds[0] || '');
    const comportamentoLocalizador = (comportCod !== '' && comportCod !== 'null') ? (mapaComport.get(comportCod) || `Código ${comportCod}`) : '';

    const locPrincIds = obterValoresSelecionadosSelect(docResp, 'selNovoLocalizador');
    const locPrincId = agQuery.get('selNovoLocalizador') || locPrincIds[0] || '';
    const localizadorPrincipal = (locPrincId && locPrincId !== 'null') ? (mapaLocs.get(locPrincId) || `ID: ${locPrincId}`) : '';

    const locSecDomIds = obterValoresSelecionadosSelect(docResp, 'selLocalizadorSecundario');
    const locSecAgIds = agQuery.getAll('selLocalizadorSecundario[]');
    const localizadoresSecundarios = resolverIdsParaTextos([...locSecDomIds, ...locSecAgIds], mapaLocs);

    const mcLocDesativarRaw = extrairLiteralJsString(html, 'mc_selLocalizadorDesativar');
    const locDesDomIds = obterValoresSelecionadosSelect(docResp, 'selLocalizadorDesativar');
    const locDesAgIds = agQuery.getAll('selLocalizadorDesativar[]');
    const locDesMcIds = mcLocDesativarRaw ? mcLocDesativarRaw.split(',').map(s => s.trim()).filter(Boolean) : [];
    const localizadoresRemover = resolverIdsParaTextos([...locDesMcIds, ...locDesDomIds, ...locDesAgIds], mapaLocs);

    // Modelo e Matriz
    const inpTxtModelo = docResp.getElementById('txtModelo');
    const rawModeloTxt = extrairLiteralJsString(html, 'mc_txtModelo')
      || agQuery.get('txtModelo')
      || (inpTxtModelo ? (inpTxtModelo.value || inpTxtModelo.getAttribute('value') || '') : '');
    const rawModeloCod = extrairLiteralJsString(html, 'mc_modelo')
      || agQuery.get('txtModeloPadrao')
      || '';
    const { modeloNome, modeloCod } = extrairModeloECodigo(rawModeloTxt, camposP, rawModeloCod);
    const inpHdnModelo = docResp.getElementById('hdnIdModelo');
    const modeloMatrizId = extrairLiteralJsString(html, 'mc_numIdModeloMatriz')
      || extrairLiteralJsString(html, 'mc_idModelo')
      || agQuery.get('hdnIdModelo')
      || (inpHdnModelo ? (inpHdnModelo.value || inpHdnModelo.getAttribute('value') || '') : '')
      || String(camposP.TipoDocumento || '');

    // Evento Principal e Complementares
    const inpTxtEv = docResp.getElementById('txtEvento');
    const inpHdnEv = docResp.getElementById('hdnEvento');
    const eventoNome = extrairLiteralJsString(html, 'mc_txtEvento')
      || agQuery.get('txtEvento')
      || (inpTxtEv ? (inpTxtEv.value || inpTxtEv.getAttribute('value') || '') : '');
    const eventoCod = extrairLiteralJsString(html, 'mc_hdnEvento')
      || agQuery.get('hdnEvento')
      || (inpHdnEv ? (inpHdnEv.value || inpHdnEv.getAttribute('value') || '') : '');

    const chkEvAgDom = docResp.getElementById('chkEventoAgendamento');
    const mcChkEvAg = extrairLiteralJsString(html, 'mc_chkEventoAgendamento');
    const temAgendamento = agQuery.get('chkEventoAgendamento') === 'S'
      || camposP.SinAgendamento === 'S'
      || mcChkEvAg === 'true'
      || (chkEvAgDom && (chkEvAgDom.checked || chkEvAgDom.hasAttribute('checked')));
    const eventoAgendado = temAgendamento ? 'Sim' : 'Não';

    const mcEvCompRaw = extrairLiteralJsString(html, 'mc_hdnEventosComplementares');
    const evCompMcIds = mcEvCompRaw ? mcEvCompRaw.split(',').map(s => s.trim()).filter(Boolean) : [];
    const evCompAgIds = [
      ...agQuery.getAll('selEventoComplementar[]'),
      ...agQuery.getAll('selectItemselEventoComplementar[]'),
      ...(agQuery.get('selEventoComplementar') ? agQuery.get('selEventoComplementar').split(/[,;]/) : []),
      ...(agQuery.get('hdnEventosComplementares') ? agQuery.get('hdnEventosComplementares').split(/[,;]/) : []),
      ...(agQuery.get('mc_hdnEventosComplementares') ? agQuery.get('mc_hdnEventosComplementares').split(/[,;]/) : [])
    ].map(s => s.trim()).filter(Boolean);
    const evCompDomIds = obterValoresSelecionadosSelect(docResp, 'selEventoComplementar');
    const todosEvCompIds = Array.from(new Set([...evCompMcIds, ...evCompAgIds, ...evCompDomIds]));
    const mapaEvComp = mesclarMapasStrings(construirMapaSelectOptions(docResp, 'selEventoComplementar'), catalogosExtras.eventosComp);
    const eventosComplementares = resolverIdsParaTextos(todosEvCompIds, mapaEvComp);

    // Dados Complementares
    const mcDadosComp = extrairLiteralJsString(html, 'mc_strDadosComplementares');
    const hdnDadosCompEl = docResp.getElementById('hdnDadosComplementares');
    const docHdnDadosComp = hdnDadosCompEl ? (hdnDadosCompEl.value || hdnDadosCompEl.getAttribute('value') || '').trim() : '';
    const rawDadosComp = mcDadosComp || agQuery.get('hdnDadosComplementares') || docHdnDadosComp || '';
    const descDadosEl = docResp.getElementById('descDadosComplementares');
    const descDadosDom = descDadosEl ? decodificarEntidadesHtml(decodeEntities(descDadosEl.textContent || '')).replace(/\s+/g, ' ').trim() : '';
    const dadosComplementares = formatarDadosComplementaresMinuta(rawDadosComp, agQuery, {
      descDadosDom,
      descDadosPrepMov: catalogosExtras.prepararMov ? catalogosExtras.prepararMov.descDadosComplementares : '',
      dadosCompSelects: catalogosExtras.prepararMov ? catalogosExtras.prepararMov.dadosCompSelects : null,
      dadosCompCatalogo: catalogosExtras.dadosCompCatalogo || null
    });

    // Encadeamento Intimação e Remessa
    const phpEncadeado = parsePhpSerializedAssoc(extrairLiteralJsString(html, 'mc_arrDadosEventoEncadeado'));
    const arrPrefIntimacao = extrairObjetoJsJson(html, 'arrPrefIntimacaoCitacao') || [];
    const prepMov = catalogosExtras.prepararMov || {};
    const prepMovRemessa = catalogosExtras.prepararMovRemessa || {};

    const mcIntimar = extrairLiteralJsString(html, 'mc_chkEncadeamentoIntimar');
    const evIntId = agQuery.get('selEventoEncadeadoCitacaoIntimacao')
      || agQuery.get('hdnEventoCitacaoIntimacao')
      || phpEncadeado.IdEventoCitacaoIntimacao
      || (camposP && camposP.selEventoEncadeadoCitacaoIntimacao && camposP.selEventoEncadeadoCitacaoIntimacao !== 'null' ? String(camposP.selEventoEncadeadoCitacaoIntimacao).trim() : '')
      || (arrPrefIntimacao[0] && arrPrefIntimacao[0].evento ? String(arrPrefIntimacao[0].evento.idEvento || '') : '')
      || '';
    const flagInt = agQuery.get('chkEncadeamentoIntimar') || phpEncadeado.chkEncadeamentoIntimar || mcIntimar || String(camposP.chkEncadeamentoIntimar || '');
    const deveIntimar = flagInt === '1' || flagInt === 'S' || flagInt === 'on' || (!!evIntId && evIntId !== 'null') || arrPrefIntimacao.length > 0;
    const mapaEvInt = mesclarMapasStrings(
      construirMapaSelectOptions(docResp, 'selEventoEncadeadoCitacaoIntimacao'),
      mesclarMapasStrings(catalogosExtras.eventosEncadeadosT, prepMov.eventosIntimacao)
    );
    const eventoIntimacao = (deveIntimar && evIntId && evIntId !== 'null')
      ? (mapaEvInt.get(evIntId) || `Cód. Evento Intimação: ${evIntId}`)
      : '';
    const prazosIntimacao = deveIntimar ? formatarPrazosIntimacaoMinuta(agQuery, arrPrefIntimacao, camposP) : '';

    const mcRemessa = extrairLiteralJsString(html, 'mc_chkEncadeamentoRemessa');
    const evRemId = agQuery.get('selEventoEncadeadoRemessa') || phpEncadeado.IdEventoRemessa || String(camposP.selEventoEncadeadoRemessa || '');
    const orgRemId = agQuery.get('selOrgao') || phpEncadeado.IdOrgaoDestino || extrairLiteralJsString(html, 'mc_selOrgao') || '';
    const flagRem = agQuery.get('chkEncadeamentoRemessa') || phpEncadeado.chkEncadeamentoRemessa || mcRemessa || String(camposP.chkEncadeamentoRemessa || '');
    const deveRemeter = flagRem === '1' || flagRem === 'S' || flagRem === 'on' || (!!evRemId && evRemId !== 'null') || (!!orgRemId && orgRemId !== 'null');
    const mapaEvRem = mesclarMapasStrings(
      construirMapaSelectOptions(docResp, 'selEventoEncadeadoRemessa'),
      mesclarMapasStrings(catalogosExtras.eventosEncadeadosR, prepMov.eventosRemessa)
    );
    const mapaOrgaos = mesclarMapasStrings(
      construirMapaSelectOptions(docResp, 'selOrgao'),
      mesclarMapasStrings(prepMovRemessa.orgaos, prepMov.orgaos)
    );
    const eventoRemessa = (deveRemeter && evRemId && evRemId !== 'null') ? (mapaEvRem.get(evRemId) || `ID: ${evRemId}`) : '';
    const orgaoRemessa = (deveRemeter && orgRemId && orgRemId !== 'null') ? (mapaOrgaos.get(orgRemId) || `ID: ${orgRemId}`) : '';

    // Classificações de Conteúdo: prioriza apenas a fonte oficial carregada pelo eproc
    // (camposPersonalizadosOrdem.IdClassificacao ou #selClassificacaoConteudo no DOM),
    // ignorando selClassificacaoConteudoIds legado dentro de Agendamento.
    const classifsResolvidas = [];
    const mapaClassif = new Map(catalogosExtras.classificacoes || []);
    const mSelect2Classif = html.match(/selClassificacaoConteudo[^)]*\)\s*\.select2\(\s*['"]data['"]\s*,\s*(\[[\s\S]*?\])\s*\)/);
    const idsSelect2 = (mSelect2Classif && mSelect2Classif[1])
      ? extrairItensSelect2OuIds(mSelect2Classif[1], mapaClassif)
      : [];
    const inpClassif = docResp.getElementById('selClassificacaoConteudo') || docResp.querySelector('input[name="selClassificacaoConteudoIds"]');
    const valInpClassif = inpClassif ? (inpClassif.value || inpClassif.getAttribute('value') || '') : '';
    const idsDomInp = valInpClassif ? extrairItensSelect2OuIds(valInpClassif, mapaClassif) : [];
    const temCamposIdClassif = camposP && Object.prototype.hasOwnProperty.call(camposP, 'IdClassificacao');
    const idsCamposP = (camposP && camposP.IdClassificacao)
      ? extrairItensSelect2OuIds(camposP.IdClassificacao, mapaClassif)
      : [];

    const classifRawIds = (
      idsDomInp.length > 0
        ? idsDomInp
        : (idsCamposP.length > 0 ? idsCamposP : idsSelect2)
    ).map(s => s.trim()).filter(s => s && s !== 'null');

    const classifTextosDom = [];
    docResp.querySelectorAll('#s2id_selClassificacaoConteudo .select2-search-choice div').forEach(el => {
      const t = decodificarEntidadesHtml(decodeEntities(el.textContent || '')).trim();
      if (t) classifTextosDom.push(t);
    });
    if (classifRawIds.length > 0) {
      classifsResolvidas.push(...resolverIdsParaTextos(classifRawIds, mapaClassif));
    } else if (!temCamposIdClassif && classifTextosDom.length > 0) {
      classifsResolvidas.push(...classifTextosDom);
    }

    // Descrição da Minuta, Assinante, Tratamento, Sigilo, Status Destino e Extras
    const inpDesc = docResp.getElementById('txtDescricao');
    const descricaoMinuta = decodificarEntidadesHtml(decodeEntities(
      agQuery.get('txtDescricao')
      || (camposP.Descricao !== undefined ? String(camposP.Descricao) : '')
      || (inpDesc ? (inpDesc.value || inpDesc.getAttribute('value') || '') : '')
    )).trim();

    const assinIds = obterValoresSelecionadosSelect(docResp, 'selAssinante');
    const assinId = agQuery.get('selAssinante')
      || extrairLiteralJsString(html, 'mc_usuarioAssinanteIndicado')
      || String(camposP.IdUsuarioAssinanteIndicado || '')
      || assinIds[0]
      || 'null';
    const assinante = (assinId && assinId !== 'null')
      ? (mapaAssinantes.get(assinId) || `ID: ${assinId}`)
      : 'Magistrado atuante no juízo';

    const tratIds = obterValoresSelecionadosSelect(docResp, 'selTratamento');
    const tratCod = agQuery.get('selTratamento')
      || extrairLiteralJsString(html, 'mc_numIdTratamentoAssinanteIndicado')
      || String(camposP.CodTratamentoAssinante ?? '')
      || tratIds[0]
      || '';
    const tratamento = (tratCod && tratCod !== '-1' && tratCod !== 'null')
      ? (mapaTratamentos.get(tratCod) || `Código ${tratCod}`)
      : '';

    const sigIds = obterValoresSelecionadosSelect(docResp, 'selSigilo');
    const rawSigAg = agQuery.get('selSigilo');
    const sigCod = (rawSigAg !== null && rawSigAg !== '')
      ? rawSigAg
      : ((camposP.IdSigilo !== undefined && camposP.IdSigilo !== '') ? String(camposP.IdSigilo) : (sigIds[0] || '0'));
    const sigilo = mapaSigilos.get(String(sigCod)) || (sigCod === '0' ? 'Sem Sigilo (Nível 0)' : `Nível ${sigCod}`);

    const stIds = obterValoresSelecionadosSelect(docResp, 'selStatusMinuta');
    const stCod = agQuery.get('selStatusMinuta') || agQuery.get('hdnCodStatusMinuta') || String(camposP.CodStatusMinuta || '') || stIds[0] || '';
    const statusDestino = stCod ? (mapaStatus.get(String(stCod)) || `Código ${stCod}`) : '';

    const extras = [];
    const chkPrec = docResp.getElementById('chkPrecedenteRelevante');
    if (camposP.SinPrecedenteRelevante === 'S' || agQuery.get('chkPrecedenteRelevante') === 'on' || (chkPrec && chkPrec.hasAttribute('checked'))) {
      extras.push('Precedente relevante');
    }
    const chkJur = docResp.getElementById('chkRemeterJurisprudencia');
    if (camposP.SinJurisprudencia === 'S' || agQuery.get('chkRemeterJurisprudencia') === 'on' || (chkJur && chkJur.hasAttribute('checked'))) {
      extras.push('Enviar p/ Jurisprudência');
    }
    const destMin = agQuery.get('selDestMinuta');
    if (destMin && destMin !== '0' && destMin !== 'null') {
      extras.push(destMin === '2' ? '1 minuta por destinatário' : (destMin === '3' ? '1 minuta por endereço' : `Destinatários: ${destMin}`));
    }
    if (tratamento) {
      extras.push(`Tratamento: ${tratamento}`);
    }

    return {
      ...prefItem,
      detalhado: true,
      erroDetalhe: '',
      tipo,
      padrao,
      grupo,
      acaoPreferencial,
      modoLocalizadores,
      comportamentoLocalizador,
      localizadorPrincipal,
      localizadoresSecundarios,
      localizadoresRemover,
      modeloNome,
      modeloCod,
      modeloMatrizId,
      eventoAgendado,
      eventoNome,
      eventoCod,
      eventosComplementares,
      dadosComplementares,
      _rawDadosComp: rawDadosComp,
      _temDescDadosDom: Boolean(descDadosDom),
      intimarPartes: deveIntimar ? 'Sim' : 'Não',
      eventoIntimacao,
      prazosIntimacao,
      remeterProcesso: deveRemeter ? 'Sim' : 'Não',
      eventoRemessa,
      orgaoRemessa,
      _evIntId: (evIntId && evIntId !== 'null') ? evIntId : '',
      _evRemId: (evRemId && evRemId !== 'null') ? evRemId : '',
      _orgRemId: (orgRemId && orgRemId !== 'null') ? orgRemId : '',
      classificacao: classifsResolvidas,
      descricaoMinuta,
      assinante,
      tratamento,
      sigilo,
      statusDestino,
      opcoesExtras: extras.join(' | ')
    };
  }

  // Orquestrador genérico de contexto para telas clássicas de preferências do eproc
  async function obterContextoTelaClassicaViewer(opcoes = {}) {
    const formId = opcoes.formId || 'frmMinutaCadastro';
    const nomeAcao = opcoes.nomeAcao || 'minuta_cadastrar';
    const acaoMenu = opcoes.acaoMenu || nomeAcao;
    const acaoMenuAlt = opcoes.acaoMenuAlt || '';
    const exigeProcessoNoMenu = Boolean(opcoes.exigeProcessoNoMenu);
    const verificaDoc = typeof opcoes.verificaDocNaTela === 'function'
      ? opcoes.verificaDocNaTela
      : (doc) => Boolean(doc && doc.getElementById(formId));

    let docBase = null;
    let htmlBase = '';
    let baseHref = window.location.href;

    if (verificaDoc(document)) {
      docBase = document;
      htmlBase = document.documentElement ? document.documentElement.innerHTML : '';
    } else {
      const urlMenu = obterUrlAcaoMenu(acaoMenu) || (acaoMenuAlt ? obterUrlAcaoMenu(acaoMenuAlt) : '');
      const temHash = urlMenu && /[?&]hash=/i.test(urlMenu);
      const temProcessoNaUrl = urlMenu && /[?&](?:num_processo|txtNumProcesso)=/i.test(urlMenu);
      if (!urlMenu || !temHash || (exigeProcessoNoMenu && !temProcessoNaUrl)) {
        return {
          disponivel: false,
          motivo: opcoes.motivoIndisponivel || `Abra a tela correspondente (${acaoMenu}) no eproc 2G para visualizar as preferências deste módulo.`
        };
      }
      const resp = await fetch(urlMenu, { credentials: 'same-origin' });
      if (!resp.ok) {
        return {
          disponivel: false,
          motivo: `Não foi possível acessar a tela ${opcoes.nomeTela || acaoMenu} em segundo plano (HTTP ${resp.status}). Abra a tela correspondente e tente novamente.`
        };
      }
      htmlBase = await lerRespostaTexto(resp);
      baseHref = urlMenu;
      docBase = new DOMParser().parseFromString(htmlBase, 'text/html');
    }

    const formInfo = extrairCamposBaseFormEproc(docBase, baseHref, htmlBase, {
      formId,
      acaoPattern: opcoes.acaoPattern || acaoMenu,
      selectsExtras: opcoes.selectsExtras
    });
    const urls = extrairUrlsAjaxTelaEproc(htmlBase, docBase, baseHref, { nomeAcao });
    if (!formInfo || (!urls.urlListar && !urls.urlAutoComp)) {
      return {
        disponivel: false,
        motivo: opcoes.motivoFormNaoEncontrado || `Formulário (#${formId}) ou link do gerenciador (#listaPreferencias) não localizado nesta página.`
      };
    }

    return {
      disponivel: true,
      nomeAcao,
      docBase,
      htmlBase,
      baseHref,
      formInfo,
      urls
    };
  }

  // Orquestrador de rede e cache para Módulo Minutas
  async function obterContextoMinutaVisualizador() {
    return obterContextoTelaClassicaViewer({
      formId: 'frmMinutaCadastro',
      acaoMenu: 'minuta_cadastrar',
      nomeAcao: 'minuta_cadastrar',
      nomeTela: 'Nova Minuta',
      exigeProcessoNoMenu: true,
      motivoIndisponivel: 'Para inspecionar os campos completos das preferências de Minutas, abra a tela de "Nova Minuta" (ou a tela de qualquer processo com o menu Nova Minuta disponível).',
      motivoFormNaoEncontrado: 'Formulário de Nova Minuta ou link do gerenciador (#listaPreferencias) não localizado nesta página.'
    });
  }

  async function obterListaCompletaPreferenciasMinutas(ctx) {
    const nomeAcaoPadrao = (ctx && ctx.nomeAcao) || 'minuta_cadastrar';
    const itensTabela = [];
    const idsTabela = new Set();
    const diag = {
      urlListar: (ctx && ctx.urls && ctx.urls.urlListar) || '',
      statusListar: '',
      bytesListar: 0,
      dtRows: 0,
      qtdTabela: 0,
      erroListar: '',
      urlAutoComp: (ctx && ctx.urls && ctx.urls.urlAutoComp) || '',
      statusAutoPost: '',
      statusAutoGet: '',
      qtdXml: 0,
      erroAuto: '',
      qtdMemoria: 0,
      qtdFallbackUnidade: 0,
      trechoHtmlListar: ''
    };
    const registrarItemTabela = (it) => {
      if (it && it.id && it.nome && !idsTabela.has(it.id)) {
        idsTabela.add(it.id);
        itensTabela.push(it);
      }
    };

    if (diag.urlListar) {
      try {
        const resp = await fetch(diag.urlListar, { credentials: 'same-origin' });
        diag.statusListar = `${resp.status}`;
        if (resp.ok) {
          const html = await lerRespostaTexto(resp);
          diag.bytesListar = html ? html.length : 0;
          const doc = new DOMParser().parseFromString(html, 'text/html');
          parseTabelaFormularioPersonalizacaoListar(doc).forEach(registrarItemTabela);

          // Suporte à tabela DataTables moderna (#tbl_preferencias com data-url AJAX JSON)
          const tblDt = doc.getElementById('tbl_preferencias');
          const urlDtRaw = tblDt ? (tblDt.getAttribute('data-url') || '') : '';
          if (itensTabela.length === 0 && urlDtRaw && typeof serializarObjetoAjaxEproc === 'function') {
            const urlDt = new URL(urlDtRaw.replace(/&amp;/g, '&'), ctx.baseHref || 'https://eproc2g.tjsp.jus.br/eproc/').href;
            const acaoReqEl = doc.getElementById('acao_request');
            const acaoReq = (acaoReqEl && acaoReqEl.value) ? acaoReqEl.value : nomeAcaoPadrao;
            const colsDt = [
              { data: 'col_checkbox', orderable: 'false' },
              { data: 'Descricao', orderable: 'true' },
              { data: 'SinValorPadrao', orderable: 'true' },
              { data: 'SinPainelInicial', orderable: 'true' },
              { data: 'SinPreferenciaIndividual', orderable: 'true' },
              { data: 'DescricaoGrupoFormularioPersonalizacaoGrupo', orderable: 'true' },
              { data: 'col_acoes', orderable: 'false' }
            ];
            let start = 0;
            const pageLen = 500;
            let totalRecs = Infinity;
            let draw = 1;
            while (start < totalRecs && draw <= 20) {
              const payloadDt = {
                draw: String(draw),
                start: String(start),
                length: String(pageLen),
                'search[value]': '',
                'search[regex]': 'false',
                'order[0][column]': '1',
                'order[0][dir]': 'asc',
                acao_request: acaoReq
              };
              colsDt.forEach((c, idx) => {
                payloadDt[`columns[${idx}][data]`] = c.data;
                payloadDt[`columns[${idx}][name]`] = '';
                payloadDt[`columns[${idx}][searchable]`] = 'true';
                payloadDt[`columns[${idx}][orderable]`] = c.orderable;
                payloadDt[`columns[${idx}][search][value]`] = '';
                payloadDt[`columns[${idx}][search][regex]`] = 'false';
              });
              const respDt = await fetch(urlDt, {
                method: 'POST',
                credentials: 'same-origin',
                headers: {
                  'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8',
                  'X-Requested-With': 'XMLHttpRequest'
                },
                body: serializarObjetoAjaxEproc(payloadDt)
              });
              if (!respDt.ok) break;
              const txtDt = await lerRespostaTexto(respDt);
              const jsonDt = JSON.parse(txtDt);
              const rowsDt = Array.isArray(jsonDt.data) ? jsonDt.data : [];
              if (typeof jsonDt.recordsTotal === 'number') totalRecs = jsonDt.recordsTotal;
              if (rowsDt.length === 0) break;
              rowsDt.forEach(r => {
                const id = String(r.IdFormularioPersonalizacao || r.DT_RowId || '').trim();
                const nome = decodificarEntidadesHtml(decodeEntities(String(r.Descricao || '').replace(/<[^>]+>/g, ''))).trim();
                const normFlag = (v, simLabel, naoLabel) => {
                  if (v === true) return simLabel;
                  if (v === false) return naoLabel;
                  const semTags = String(v === null || v === undefined ? '' : v).replace(/<[^>]+>/g, ' ').trim();
                  const s = normalizar(semTags);
                  if (!s) return '';
                  return (s === 's' || s === 'sim' || s === '1' || s === 'true') ? simLabel : ((s === 'n' || s === 'nao' || s === '0' || s === 'false') ? naoLabel : semTags);
                };
                const rawTipo = normalizar(String(r.SinPreferenciaIndividual === null || r.SinPreferenciaIndividual === undefined ? '' : r.SinPreferenciaIndividual).replace(/<[^>]+>/g, ' '));
                const tipoTxt = (rawTipo === 'n' || rawTipo === 'nao' || rawTipo === 'u' || rawTipo === 'unidade' || rawTipo === 'false' || rawTipo === '0')
                  ? 'Unidade'
                  : ((rawTipo === 's' || rawTipo === 'sim' || rawTipo === 'i' || rawTipo === 'individual' || rawTipo === 'true' || rawTipo === '1') ? 'Individual' : '');
                registrarItemTabela({
                  id,
                  nome,
                  padrao: normFlag(r.SinValorPadrao, 'Sim', 'Não'),
                  painelInicial: normFlag(r.SinPainelInicial, 'Sim', 'Não'),
                  tipo: tipoTxt,
                  grupo: decodificarEntidadesHtml(decodeEntities(r.DescricaoGrupoFormularioPersonalizacaoGrupo || '')).trim(),
                  rawObj: r,
                  urlEditar: ''
                });
                diag.dtRows++;
              });
              start += rowsDt.length;
              draw++;
              if (rowsDt.length < pageLen && start >= totalRecs) break;
            }
          }

          // Paginação clássica de formulario_personalizacao_listar quando houver mais de 1 página
          const selPag = doc.querySelector('#selInfraPaginacaoSuperior, select[id*="selInfraPaginacao"]');
          const frmPag = doc.getElementById('frmFormularioPersonalizacaoLista') || doc.querySelector('form[action*="formulario_personalizacao_listar"]');
          if (selPag && selPag.options && selPag.options.length > 1 && frmPag) {
            const actionPag = new URL((frmPag.getAttribute('action') || diag.urlListar).replace(/&amp;/g, '&'), ctx.baseHref).href;
            for (let p = 1; p < selPag.options.length; p++) {
              const pairsPag = [];
              frmPag.querySelectorAll('input[type="hidden"]').forEach(inp => {
                if (inp.name) pairsPag.push([inp.name, inp.name === 'hdnInfraPaginaAtual' ? selPag.options[p].value : inp.value]);
              });
              const respP = await fetch(actionPag, {
                method: 'POST',
                headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                body: encodeWindows1252Body(pairsPag),
                credentials: 'same-origin'
              });
              if (respP.ok) {
                const htmlP = await lerRespostaTexto(respP);
                const docP = new DOMParser().parseFromString(htmlP, 'text/html');
                parseTabelaFormularioPersonalizacaoListar(docP).forEach(registrarItemTabela);
              }
            }
          }

          if (itensTabela.length === 0 && html) {
            const plain = html.replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
            diag.trechoHtmlListar = plain.slice(0, 140);
          }
        }
      } catch (e) {
        diag.erroListar = e.message || String(e);
        console.warn('[Visualizador Minutas] Falha ao ler formulario_personalizacao_listar:', e);
      }
    }
    diag.qtdTabela = itensTabela.length;

    let mapaXml = new Map();
    if (diag.urlAutoComp) {
      try {
        // 1. Tenta POST padrão com txtPreferencia= (mesmo protocolo usado em obterPreferenciaRelatorioExistentes)
        const respPost = await fetch(diag.urlAutoComp, {
          method: 'POST',
          credentials: 'same-origin',
          headers: {
            'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8',
            'X-Requested-With': 'XMLHttpRequest'
          },
          body: 'txtPreferencia='
        });
        diag.statusAutoPost = `${respPost.status}`;
        if (respPost.ok) {
          const txtPost = await lerRespostaTexto(respPost);
          mapaXml = parseXmlPreferenciasAutoCompletar(txtPost);
        }

        // 2. Fallback GET (como InfraAjax.listarPreferencias faz quando txtPreferencia está vazio)
        if (mapaXml.size === 0) {
          const respGet = await fetch(diag.urlAutoComp, {
            credentials: 'same-origin',
            headers: { 'X-Requested-With': 'XMLHttpRequest' }
          });
          diag.statusAutoGet = `${respGet.status}`;
          if (respGet.ok) {
            const txtGet = await lerRespostaTexto(respGet);
            mapaXml = parseXmlPreferenciasAutoCompletar(txtGet);
          }
        }
      } catch (e) {
        diag.erroAuto = e.message || String(e);
        console.warn('[Visualizador Minutas] Falha ao ler XML autocomplete:', e);
      }
    }
    diag.qtdXml = mapaXml.size;

    const mesmoDoc = !ctx || !ctx.docBase || (typeof document !== 'undefined' && ctx.docBase === document);
    const itensMemoria = (mesmoDoc && window.objAjaxAutoCompPreferencia && Array.isArray(window.objAjaxAutoCompPreferencia.arrItens))
      ? window.objAjaxAutoCompPreferencia.arrItens
      : [];
    diag.qtdMemoria = itensMemoria.length;

    let resultadoFinal = mesclarListaPreferenciasMinutas(itensTabela, mapaXml, itensMemoria);

    // 3. Fallback adicional usando obterTodasPreferenciasUnidade() do próprio script se ainda vier vazio (somente Minutas)
    if (resultadoFinal.length === 0 && nomeAcaoPadrao === 'minuta_cadastrar' && typeof obterTodasPreferenciasUnidade === 'function' && mesmoDoc) {
      try {
        const legadas = await obterTodasPreferenciasUnidade();
        if (Array.isArray(legadas) && legadas.length > 0) {
          resultadoFinal = legadas.map(it => ({
            id: String(it.id || '').trim(),
            nome: String(it.nome || '').trim(),
            padrao: '',
            painelInicial: '',
            tipo: '',
            grupo: '',
            urlEditar: ''
          })).filter(it => it.id && it.nome);
          diag.qtdFallbackUnidade = resultadoFinal.length;
        }
      } catch (eLeg) {}
    }

    if (ctx) ctx._diagLista = diag;
    if (resultadoFinal.length === 0) {
      console.warn(`[Visualizador ${nomeAcaoPadrao}] Nenhuma preferência retornada. Diagnóstico:`, diag);
    }
    return resultadoFinal;
  }

  function obterCacheCatalogosMinutaViewer() {
    if (!window._eprocCacheCatalogosMinutaViewer) {
      window._eprocCacheCatalogosMinutaViewer = {
        classificacoes: null,
        eventosCompPorEvento: new Map(),
        prepararMovPorEvento: new Map(),
        eventosEncadeadosPorTipo: new Map(),
        dadosCompCatalogo: null,
        localizadoresExtra: null,
        localizadoresRelatorio: null,
        subframeDadosComp: new Map()
      };
    }
    return window._eprocCacheCatalogosMinutaViewer;
  }

  function obterCacheDetalhesModuloViewer(modulo = 'minutas', limpar = false) {
    if (modulo === 'minutas') {
      if (limpar || !window._eprocCacheDetalhesPrefsMinutas) {
        window._eprocCacheDetalhesPrefsMinutas = new Map();
      }
      return window._eprocCacheDetalhesPrefsMinutas;
    }
    if (!window._eprocCacheDetalhesPrefsPorModulo) {
      window._eprocCacheDetalhesPrefsPorModulo = {};
    }
    if (limpar || !window._eprocCacheDetalhesPrefsPorModulo[modulo]) {
      window._eprocCacheDetalhesPrefsPorModulo[modulo] = new Map();
    }
    return window._eprocCacheDetalhesPrefsPorModulo[modulo];
  }

  async function obterCatalogoEncadeadoViewer(tipo /* 'T' | 'R' */, ctx) {
    const t = String(tipo || '').toUpperCase() === 'R' ? 'R' : 'T';
    const selectId = t === 'R' ? 'selEventoEncadeadoRemessa' : 'selEventoEncadeadoCitacaoIntimacao';
    const cache = obterCacheCatalogosMinutaViewer();
    if (!cache.eventosEncadeadosPorTipo) cache.eventosEncadeadosPorTipo = new Map();
    if (cache.eventosEncadeadosPorTipo.has(t)) return cache.eventosEncadeadosPorTipo.get(t);

    let mapa = new Map();
    const lerDocSelect = (d) => {
      if (!d) return;
      const mId = construirMapaSelectOptions(d, selectId);
      mId.forEach((v, k) => { if (!mapa.has(k)) mapa.set(k, v); });
      if (mId.size === 0 && typeof d.querySelectorAll === 'function') {
        d.querySelectorAll('select').forEach(sel => {
          const idLow = (sel.id || sel.name || '').toLowerCase();
          if (t === 'R' && !idLow.includes('remessa') && d.querySelectorAll('select').length > 1) return;
          if (t === 'T' && !idLow.includes('intimacao') && !idLow.includes('citacao') && d.querySelectorAll('select').length > 1) return;
          sel.querySelectorAll('option').forEach(opt => {
            const val = (opt.value || opt.getAttribute('value') || '').trim();
            const txt = decodificarEntidadesHtml(decodeEntities(opt.textContent || '')).replace(/\s+/g, ' ').trim();
            if (val && val !== 'null' && txt && !/^\[?\s*(desmarcar|selecione)/i.test(txt) && !mapa.has(val)) {
              mapa.set(val, txt);
            }
          });
        });
      }
    };

    if (typeof document !== 'undefined') lerDocSelect(document);
    if (ctx && ctx.docBase && ctx.docBase !== (typeof document !== 'undefined' ? document : null)) {
      lerDocSelect(ctx.docBase);
    }

    if (mapa.size === 0 && ctx && ctx.urls && ctx.urls.urlEncadearEvento) {
      try {
        const resp = await fetch(ctx.urls.urlEncadearEvento, {
          method: 'POST',
          headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
          body: `strTipo=${encodeURIComponent(t)}&strValor=1&strSinAutomatizacao=`,
          credentials: 'same-origin'
        });
        if (resp.ok) {
          let htmlRet = await lerRespostaTexto(resp);
          if (htmlRet.includes('<resultado>') || htmlRet.includes('menorque')) {
            const xml = new DOMParser().parseFromString(htmlRet, 'text/xml');
            const resEl = xml.querySelector('resultado');
            htmlRet = (resEl ? (resEl.textContent || '') : htmlRet)
              .replace(/&nbsp/gi, '&nbsp;')
              .replace(/menorque/gi, '<')
              .replace(/maiorque/gi, '>')
              .replace(/ecomercial/gi, '&');
          }
          const docRet = new DOMParser().parseFromString(htmlRet, 'text/html');
          lerDocSelect(docRet);
        }
      } catch (e) {}
    }

    cache.eventosEncadeadosPorTipo.set(t, mapa);
    return mapa;
  }

  async function obterCatalogoDadosComplementaresViewer(ctx) {
    const cache = obterCacheCatalogosMinutaViewer();
    if (cache.dadosCompCatalogo) return cache.dadosCompCatalogo;

    const pares = new Map();
    const campos = new Map();
    const registrarSelect = (docTarget) => {
      if (!docTarget || typeof docTarget.getElementById !== 'function') return false;
      const sel = docTarget.getElementById('selDadoComplementar');
      if (!sel || typeof sel.querySelectorAll !== 'function') return false;
      let qtd = 0;
      sel.querySelectorAll('option').forEach(opt => {
        const val = (opt.value || opt.getAttribute('value') || '').trim();
        const txt = decodificarEntidadesHtml(decodeEntities(opt.textContent || '')).replace(/\s+/g, ' ').trim();
        if (!val || val === 'null' || !val.includes('|') || !txt) return;
        const [idCampo, idValor] = val.split('|').map(s => s.trim());
        if (!idCampo || !idValor) return;
        const ultTraco = txt.lastIndexOf('-');
        let campoNome = txt;
        let valorNome = '';
        let formatado = txt;
        if (ultTraco > 0 && ultTraco < txt.length - 1) {
          campoNome = txt.slice(0, ultTraco).trim();
          valorNome = txt.slice(ultTraco + 1).trim();
          formatado = `${campoNome}: ${valorNome}`;
        }
        pares.set(`${idCampo}|${idValor}`, formatado);
        if (!campos.has(idCampo)) campos.set(idCampo, { label: campoNome, options: new Map() });
        if (valorNome) campos.get(idCampo).options.set(idValor, valorNome);
        qtd++;
      });
      return qtd > 0;
    };

    let achou = false;
    if (typeof document !== 'undefined') achou = registrarSelect(document);
    if (!achou && ctx && ctx.docBase) achou = registrarSelect(ctx.docBase);

    if (!achou && ctx && ctx.urls) {
      const candidatas = [ctx.urls.urlMinutaAreaTrabalho, ctx.urls.urlAutomatizarLoc].filter(Boolean);
      for (const urlCat of candidatas) {
        try {
          const resp = await fetch(urlCat, { credentials: 'same-origin' });
          if (resp.ok) {
            const html = await lerRespostaTexto(resp);
            const docCat = new DOMParser().parseFromString(html, 'text/html');
            if (registrarSelect(docCat)) {
              achou = true;
              break;
            }
          }
        } catch (e) {}
      }
    }

    const res = { pares, campos };
    cache.dadosCompCatalogo = res;
    return res;
  }

  async function obterCatalogoLocalizadoresExtraViewer(ctx) {
    const cache = obterCacheCatalogosMinutaViewer();
    if (cache.localizadoresExtra && cache.localizadoresExtra.size > 0) return cache.localizadoresExtra;
    const mapa = new Map();

    const adicionarAoMapa = (k, v) => {
      const id = String(k || '').trim();
      const txt = String(v || '').trim();
      if (id && id !== 'null' && txt && !mapa.has(id)) {
        mapa.set(id, decodificarEntidadesHtml(decodeEntities(txt)).replace(/\s+/g, ' ').trim());
      }
    };

    // 1. Colhe de selects do document vivo
    if (typeof document !== 'undefined') {
      ['selNovoLocalizador', 'selLocalizadorSecundario', 'selLocalizadorDesativar', 'selLocalizador', 'selLocalizadores'].forEach(sid => {
        const subM = construirMapaSelectOptions(document, sid);
        subM.forEach((v, k) => adicionarAoMapa(k, v));
      });
    }

    // 2. Colhe de nomeLocalizadores (scripts do DOM, htmlBase, etc.)
    const mapaNomesDoc = (typeof obterMapaNomeLocalizadoresGlobal === 'function')
      ? obterMapaNomeLocalizadoresGlobal(ctx && ctx.docBase, (ctx && ctx.htmlBase) || '')
      : new Map();
    mapaNomesDoc.forEach((v, k) => adicionarAoMapa(k, v));

    // 2b. Colhe de window.nomeLocalizadores
    if (typeof window !== 'undefined' && window.nomeLocalizadores && typeof window.nomeLocalizadores === 'object') {
      Object.entries(window.nomeLocalizadores).forEach(([id, dados]) => {
        const rot = Array.isArray(dados) ? dados[0] : (typeof dados === 'string' ? dados : (dados.name || dados.descricao || ''));
        if (rot) adicionarAoMapa(id, rot);
      });
    }

    // 3. Colhe de ctx.docBase
    if (ctx && ctx.docBase) {
      ['selNovoLocalizador', 'selLocalizadorSecundario', 'selLocalizadorDesativar', 'selLocalizador', 'selLocalizadores'].forEach(sid => {
        const subM = construirMapaSelectOptions(ctx.docBase, sid);
        subM.forEach((v, k) => adicionarAoMapa(k, v));
      });
    }

    // 4. Tenta obterLocalizadoresOrgaoEproc() se disponível
    try {
      if (typeof obterLocalizadoresOrgaoEproc === 'function') {
        const lista = await obterLocalizadoresOrgaoEproc();
        (lista || []).forEach(it => {
          if (it && it.id && (it.nomeCurto || it.nomeCompleto)) {
            const rot = (it.nomeCurto && it.nomeCompleto && it.nomeCurto !== it.nomeCompleto)
              ? `${it.nomeCurto} - ${it.nomeCompleto}`
              : (it.nomeCompleto || it.nomeCurto);
            adicionarAoMapa(it.id, rot);
          }
        });
      }
    } catch (e) {}

    // 5. Se houver URL de localizadores do órgão (colhe tabela completa de localizadores)
    if (ctx && ctx.urls && ctx.urls.urlLocalizadoresOrgao) {
      try {
        const resp = await fetch(ctx.urls.urlLocalizadoresOrgao, { credentials: 'same-origin' });
        if (resp.ok) {
          const html = await lerRespostaTexto(resp);
          const doc = new DOMParser().parseFromString(html, 'text/html');
          doc.querySelectorAll('tr').forEach(tr => {
            const mId = (tr.innerHTML || '').match(/id_localizador_orgao=(\d+)/i);
            const tds = tr.querySelectorAll('td');
            if (mId && tds.length >= 3) {
              const col1 = decodificarEntidadesHtml(decodeEntities(tds[1].textContent || '')).replace(/\u00a0/g, ' ').trim();
              const col2 = decodificarEntidadesHtml(decodeEntities(tds[2].textContent || '')).replace(/\u00a0/g, ' ').trim();
              const rot = (col2 && col1 && col2 !== col1) ? `${col2} - ${col1}` : (col1 || col2);
              if (rot) adicionarAoMapa(mId[1], rot);
            }
          });
        }
      } catch (e) {}
    }

    // 6. Fallback final: se ainda vazio, busca a página de Nova Minuta para extrair selNovoLocalizador
    if (mapa.size === 0 && typeof obterUrlAcaoMenu === 'function') {
      try {
        const urlMin = obterUrlAcaoMenu('minuta_cadastrar');
        if (urlMin) {
          const resp = await fetch(urlMin, { credentials: 'same-origin' });
          if (resp.ok) {
            const html = await lerRespostaTexto(resp);
            const doc = new DOMParser().parseFromString(html, 'text/html');
            const subM = construirMapaSelectOptions(doc, 'selNovoLocalizador');
            subM.forEach((v, k) => adicionarAoMapa(k, v));
          }
        }
      } catch (e) {}
    }

    if (mapa.size > 0) {
      cache.localizadoresExtra = mapa;
    }
    return mapa;
  }

  async function obterCatalogoClassificacoesViewer(ctx) {
    const cache = obterCacheCatalogosMinutaViewer();
    if (cache.classificacoes) return cache.classificacoes;

    const mapaPorId = new Map();
    const registrar = (obj) => {
      if (obj && obj.id && obj.text && !mapaPorId.has(String(obj.id))) {
        mapaPorId.set(String(obj.id), String(obj.text));
      }
    };

    if (typeof cacheClassificacoesUnidade !== 'undefined' && cacheClassificacoesUnidade instanceof Map) {
      cacheClassificacoesUnidade.forEach(v => registrar(v));
    }

    if (mapaPorId.size === 0 && ctx && ctx.urls && ctx.urls.urlListarClassif) {
      try {
        if (document.getElementById('frmMinutaCadastro') && typeof carregarTodasClassificacoesDaTabela === 'function') {
          const mapaNomes = await carregarTodasClassificacoesDaTabela();
          mapaNomes.forEach(v => registrar(v));
        }
        if (mapaPorId.size === 0) {
          const resp = await fetch(ctx.urls.urlListarClassif, { credentials: 'same-origin' });
          if (resp.ok) {
            const html = await lerRespostaTexto(resp);
            const doc = new DOMParser().parseFromString(html, 'text/html');
            doc.querySelectorAll('tr').forEach(tr => {
              if (tr.querySelector('th')) return;
              const chk = tr.querySelector('input[type="checkbox"]:not([id*="SelecionarTodos"]):not([name*="SelecionarTodos"])');
              let id = chk ? (chk.value || '').trim() : '';
              if (!/^\d+$/.test(id)) {
                const m = tr.innerHTML.match(/id_classificacao(?:_conteudo)?=(\d+)/i) || tr.innerHTML.match(/[?&]id=(\d+)/i);
                if (m) id = m[1];
              }
              const tds = Array.from(tr.querySelectorAll('td'));
              let nome = tds[1] ? decodificarEntidadesHtml(decodeEntities(tds[1].textContent || '')).trim() : '';
              if (!nome) {
                for (let i = 1; i < tds.length; i++) {
                  const cand = decodificarEntidadesHtml(decodeEntities(tds[i].textContent || '')).trim();
                  if (cand && !tds[i].querySelector('input[type="checkbox"]')) { nome = cand; break; }
                }
              }
              if (/^\d+$/.test(id) && nome) registrar({ id, text: nome });
            });
          }
        }
      } catch (e) {}
    }

    cache.classificacoes = mapaPorId;
    return mapaPorId;
  }

  async function obterCatalogoEventosCompViewer(idEvento, ctx) {
    const ev = String(idEvento || '').trim();
    if (!ev || !ctx || !ctx.urls || !ctx.urls.urlEventosComp) return new Map();
    const cache = obterCacheCatalogosMinutaViewer();
    if (cache.eventosCompPorEvento.has(ev)) return cache.eventosCompPorEvento.get(ev);

    const mapa = new Map();
    try {
      const resp = await fetch(ctx.urls.urlEventosComp, {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: `IdEvento=${encodeURIComponent(ev)}`,
        credentials: 'same-origin'
      });
      if (resp.ok) {
        const json = await resp.json();
        if (json && Array.isArray(json.Eventos)) {
          json.Eventos.forEach(it => {
            if (it && it.id !== undefined && it.descricao) {
              mapa.set(String(it.id).trim(), decodificarEntidadesHtml(decodeEntities(it.descricao)).trim());
            }
          });
        }
      }
    } catch (e) {}

    cache.eventosCompPorEvento.set(ev, mapa);
    return mapa;
  }

  function extrairTextoDescDadosComplementaresFrag(docFrag, fragHtml) {
    if (!docFrag) return '';
    const limparFrag = (htmlOuTexto) => {
      return decodificarEntidadesHtml(decodeEntities(
        String(htmlOuTexto || '')
          .replace(/<br\s*\/?>/gi, ' | ')
          .replace(/<\/(?:p|div|li|tr)>/gi, ' | ')
          .replace(/<\/(?:td|th|b|strong|span)>/gi, ' ')
          .replace(/<[^>]+>/g, ' ')
      ))
        .replace(/\s+/g, ' ')
        .replace(/(?:\s*\|\s*){2,}/g, ' | ')
        .replace(/^\s*\|\s*|\s*\|\s*$/g, '')
        .trim();
    };

    const elDesc = docFrag.getElementById('descDadosComplementares') || docFrag.getElementById('descDadosAutuacao');
    if (elDesc) {
      const txt = limparFrag(elDesc.innerHTML || elDesc.textContent || '');
      if (txt) return txt;
    }

    if (fragHtml) {
      const mJs = fragHtml.match(/descDadosComplementares['"]\s*\)\s*\.\s*(?:html|text)\(\s*(['"])([\s\S]*?)\1\s*\)/i)
        || fragHtml.match(/getElementById\(\s*['"]descDadosComplementares['"]\s*\)\s*\.\s*(?:innerHTML|textContent)\s*=\s*(['"])([\s\S]*?)\1/i);
      if (mJs && mJs[2]) {
        const txtJs = limparFrag(mJs[2].replace(/\\'/g, "'").replace(/\\"/g, '"').replace(/\\\//g, '/'));
        if (txtJs) return txtJs;
      }
    }
    return '';
  }

  function extrairUrlSubframeDadosComplementares(docFrag, fragHtml, baseUrl) {
    const candidatos = [];
    if (docFrag && typeof docFrag.querySelectorAll === 'function') {
      docFrag.querySelectorAll('button[onclick*="exibirSubFrm"], input[onclick*="exibirSubFrm"], a[onclick*="exibirSubFrm"]').forEach(el => {
        const on = el.getAttribute('onclick') || '';
        const m = on.match(/exibirSubFrm\s*\(\s*['"]([^'"]+)['"]/i);
        if (m && m[1]) candidatos.push(m[1]);
      });
    }
    if (fragHtml) {
      const reSub = /exibirSubFrm\s*\(\s*['"]([^'"]+)['"]/gi;
      let m;
      while ((m = reSub.exec(fragHtml)) !== null) {
        if (m[1]) candidatos.push(m[1]);
      }
      const reUrlDir = /controlador\.php\?[^'"\s<>)]*(?:dados_complementares|agendar_alteracao|alterar_dados)[^'"\s<>)]*/gi;
      while ((m = reUrlDir.exec(fragHtml)) !== null) {
        if (m[0]) candidatos.push(m[0]);
      }
    }
    const escolhido = candidatos.find(u => /dados_complementares|agendar_alteracao|alterar_dados|autuacao/i.test(u))
      || candidatos.find(u => !/localizador|intimacao/i.test(u))
      || '';
    if (!escolhido) return '';
    const unescaped = escolhido.replace(/&amp;/gi, '&').trim();
    try {
      const refBase = baseUrl || (typeof location !== 'undefined' ? location.href : 'https://eproc2g.tjsp.jus.br/eproc/');
      return new URL(unescaped, refBase).href;
    } catch (e) {
      return unescaped;
    }
  }

  function indexarSelectsDadosComplementaresDeDoc(docTarget, destino, incluirTodosSelects = false) {
    if (!docTarget || typeof docTarget.querySelectorAll !== 'function' || !destino) return;
    const selects = docTarget.querySelectorAll(
      incluirTodosSelects
        ? 'select'
        : 'select[id*="DadoComplementar"], select[name*="DadoComplementar"], select[id*="DadosComplementares"], select[name*="DadosComplementares"]'
    );
    selects.forEach(sel => {
      const rawId = (sel.id || '').trim();
      const rawName = (sel.name || '').trim();
      const chaveBase = (rawId || rawName).replace(/\[\]$/, '').trim();
      if (!chaveBase) return;
      if (/^(?:selInfra|selEvento|selOrgao|selNovoLocalizador|selLocalizador|selModelo|selAssinante|selTratamento|selSigilo|selStatusMinuta|selFormulario|selOpcaoLocalizador|selDestMinuta)/i.test(chaveBase)) {
        return;
      }

      const lblEl = rawId ? docTarget.querySelector(`label[for="${rawId}"]`) : null;
      let label = lblEl ? decodificarEntidadesHtml(decodeEntities(lblEl.textContent || '')).replace(/:$/, '').trim() : '';
      if (!label && typeof sel.getAttribute === 'function') {
        label = (sel.getAttribute('aria-label') || sel.getAttribute('data-label') || sel.getAttribute('title') || '').trim();
      }
      if (!label && typeof sel.closest === 'function') {
        const tr = sel.closest('tr');
        if (tr) {
          const ancestrais = new Set();
          for (let p = sel; p; p = p.parentNode) ancestrais.add(p);
          const tdLabel = Array.from(tr.querySelectorAll('td, th, label')).find(cel => !ancestrais.has(cel) && (cel.textContent || '').trim());
          if (tdLabel) {
            label = decodificarEntidadesHtml(decodeEntities(tdLabel.textContent || '')).replace(/:$/, '').trim();
          }
        }
      }
      if (!label) label = chaveBase;

      const opts = rawId ? construirMapaSelectOptions(docTarget, rawId) : new Map();
      if (opts.size === 0 && typeof sel.querySelectorAll === 'function') {
        sel.querySelectorAll('option').forEach(opt => {
          const val = (opt.value || opt.getAttribute('value') || '').trim();
          const txt = decodificarEntidadesHtml(decodeEntities(opt.textContent || '')).replace(/\s+/g, ' ').trim();
          if (val && val !== 'null' && txt && !/^selecione/i.test(txt)) {
            opts.set(val, txt);
          }
        });
      }

      const info = { label, options: opts };
      destino.set(chaveBase, info);
      const mColchete = chaveBase.match(/\[(\d+)\]$/);
      if (mColchete && mColchete[1] && !destino.has(mColchete[1])) {
        destino.set(mColchete[1], info);
      }
    });
  }

  async function obterCatalogoPrepararMovViewer(idEvento, ctx, rawDadosComp = '', opcoes = {}) {
    const ev = String(idEvento || '').trim();
    const rawComp = String(rawDadosComp || '').trim();
    const vazio = {
      eventosIntimacao: new Map(),
      eventosRemessa: new Map(),
      orgaos: new Map(),
      dadosCompSelects: new Map(),
      descDadosComplementares: ''
    };
    if (!ev || !ctx || !ctx.urls || !ctx.urls.urlPrepararMov) return vazio;

    const cache = obterCacheCatalogosMinutaViewer();
    if (!cache.subframeDadosComp) cache.subframeDadosComp = new Map();
    const chaveCache = `${ev}::${rawComp}`;
    if (cache.prepararMovPorEvento.has(chaveCache)) return cache.prepararMovPorEvento.get(chaveCache);

    try {
      const numProc = (ctx.formInfo && ctx.formInfo.numProcesso) || '';
      const pairs = [
        ['idEvento', ev],
        ['numProcesso', numProc],
        ['movimentarProcesso', ''],
        ['bolPrepararMovimentacao', ''],
        ['idOrgaoJuizo', ''],
        ['bolControleMagistradoExterno', 'S'],
        ['acao', 'minuta_cadastrar']
      ];
      if (rawComp) {
        pairs.push(['dadosComplementares', rawComp]);
      }

      const resp = await fetch(ctx.urls.urlPrepararMov, {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: encodeWindows1252Body(pairs),
        credentials: 'same-origin'
      });
      if (resp.ok) {
        const txtXml = await lerRespostaTexto(resp);
        const xml = new DOMParser().parseFromString(txtXml, 'text/xml');
        const resEl = xml.querySelector('resultado');
        let fragHtml = resEl ? (resEl.textContent || '') : txtXml;
        fragHtml = fragHtml
          .replace(/&nbsp/gi, '&nbsp;')
          .replace(/menorque/gi, '<')
          .replace(/maiorque/gi, '>')
          .replace(/ecomercial/gi, '&');

        const docFrag = new DOMParser().parseFromString(fragHtml, 'text/html');
        const dadosCompSelects = new Map();
        indexarSelectsDadosComplementaresDeDoc(docFrag, dadosCompSelects, false);

        let descDadosComplementares = extrairTextoDescDadosComplementaresFrag(docFrag, fragHtml);

        const precisaSubframe = (rawComp.includes('±') || Boolean(opcoes && opcoes.precisaDadosComp))
          && !descDadosComplementares
          && dadosCompSelects.size === 0;

        if (precisaSubframe) {
          const baseRef = (ctx.formInfo && ctx.formInfo.actionUrl) || ctx.urls.urlPrepararMov;
          const urlSub = extrairUrlSubframeDadosComplementares(docFrag, fragHtml, baseRef);
          if (urlSub) {
            const chaveSub = `${ev}::${urlSub}`;
            let subInfo = cache.subframeDadosComp.get(chaveSub);
            if (!subInfo) {
              subInfo = { selects: new Map(), desc: '' };
              try {
                const respSub = await fetch(urlSub, { credentials: 'same-origin' });
                if (respSub.ok) {
                  const subHtml = await lerRespostaTexto(respSub);
                  const subDoc = new DOMParser().parseFromString(subHtml, 'text/html');
                  indexarSelectsDadosComplementaresDeDoc(subDoc, subInfo.selects, true);
                  subInfo.desc = extrairTextoDescDadosComplementaresFrag(subDoc, subHtml);
                }
              } catch (eSub) {}
              cache.subframeDadosComp.set(chaveSub, subInfo);
            }
            subInfo.selects.forEach((v, k) => {
              if (!dadosCompSelects.has(k)) dadosCompSelects.set(k, v);
            });
            if (!descDadosComplementares && subInfo.desc) {
              descDadosComplementares = subInfo.desc;
            }
          }
        }

        const resultado = {
          eventosIntimacao: construirMapaSelectOptions(docFrag, 'selEventoEncadeadoCitacaoIntimacao'),
          eventosRemessa: construirMapaSelectOptions(docFrag, 'selEventoEncadeadoRemessa'),
          orgaos: construirMapaSelectOptions(docFrag, 'selOrgao'),
          dadosCompSelects,
          descDadosComplementares
        };
        cache.prepararMovPorEvento.set(chaveCache, resultado);
        return resultado;
      }
    } catch (e) {}

    cache.prepararMovPorEvento.set(chaveCache, vazio);
    return vazio;
  }

  async function carregarDetalhesPreferenciaMinuta(prefItem, ctx, options = {}) {
    if (!window._eprocCacheDetalhesPrefsMinutas) {
      window._eprocCacheDetalhesPrefsMinutas = new Map();
    }
    const cacheMap = window._eprocCacheDetalhesPrefsMinutas;
    if (!options.forcarRecarga && cacheMap.has(prefItem.id)) {
      return cacheMap.get(prefItem.id);
    }

    const pairs = [
      ...(ctx.formInfo.basePairs || []),
      ['hdnAcaoPreferencia', ''],
      ['hdnPreferencia', prefItem.id],
      ['txtPreferencia', prefItem.nome],
      ['hdnPreferenciaUsuario', prefItem.complemento || ''],
      ['hdnNumIdValorSelecionadoCombo', prefItem.id],
      ['hdnStrDescricaoPreferencia', prefItem.nome],
      ['hdnStrPreferenciaUsuario', prefItem.complemento || ''],
      ['isChangePreferencia', '1']
    ];

    const resp = await fetch(ctx.formInfo.actionUrl, {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: encodeWindows1252Body(pairs),
      credentials: 'same-origin'
    });
    if (!resp.ok) {
      throw new Error(`HTTP ${resp.status} ao carregar preferência "${prefItem.nome}"`);
    }

    const htmlResp = await lerRespostaTexto(resp);
    // Inspeção rápida para saber se precisa buscar catálogos auxiliares em cache
    const preParsed = parseDetalhesPreferenciaMinutaHtml(htmlResp, prefItem, ctx, {});
    const precisaClassif = (preParsed.classificacao || []).some(c => /^ID:\s*\S+$/.test(c));
    const precisaComp = (preParsed.eventosComplementares || []).some(c => /^ID:\s*\d+$/.test(c));
    const precisaDadosComp = Boolean(preParsed.dadosComplementares && /DadoComplementar|Dado #/i.test(preParsed.dadosComplementares))
      || Boolean(preParsed._rawDadosComp && !preParsed._temDescDadosDom);
    const precisaEncInt = preParsed.intimarPartes === 'Sim' && (!preParsed.eventoIntimacao || /^Cód\./.test(preParsed.eventoIntimacao));
    const precisaEncRem = preParsed.remeterProcesso === 'Sim' && Boolean(preParsed._evRemId) && (!preParsed.eventoRemessa || /^ID:/.test(preParsed.eventoRemessa));
    const precisaOrgRem = preParsed.remeterProcesso === 'Sim' && Boolean(preParsed._evRemId) && /^ID:/.test(preParsed.orgaoRemessa);
    const precisaLocExtra = [
      preParsed.localizadorPrincipal,
      ...(preParsed.localizadoresSecundarios || []),
      ...(preParsed.localizadoresRemover || [])
    ].some(v => typeof v === 'string' && /^ID:\s*/.test(v));
    const precisaPrepMovMain = (precisaDadosComp || precisaEncInt || precisaEncRem || precisaOrgRem) && Boolean(preParsed.eventoCod);
    const precisaQualquerCatalogo = precisaClassif || precisaComp || precisaDadosComp || precisaEncInt || precisaEncRem || precisaOrgRem || precisaLocExtra;

    const [
      classificacoes,
      eventosComp,
      prepararMov,
      prepararMovRemessa,
      eventosEncadeadosT,
      eventosEncadeadosR,
      dadosCompCatalogo,
      localizadoresExtras
    ] = await Promise.all([
      precisaClassif ? obterCatalogoClassificacoesViewer(ctx) : Promise.resolve(null),
      (precisaComp && preParsed.eventoCod) ? obterCatalogoEventosCompViewer(preParsed.eventoCod, ctx) : Promise.resolve(null),
      precisaPrepMovMain
        ? obterCatalogoPrepararMovViewer(preParsed.eventoCod, ctx, preParsed._rawDadosComp || '', { precisaDadosComp })
        : Promise.resolve(null),
      (precisaOrgRem && preParsed._evRemId && preParsed._evRemId !== preParsed.eventoCod)
        ? obterCatalogoPrepararMovViewer(preParsed._evRemId, ctx)
        : Promise.resolve(null),
      precisaEncInt ? obterCatalogoEncadeadoViewer('T', ctx) : Promise.resolve(null),
      precisaEncRem ? obterCatalogoEncadeadoViewer('R', ctx) : Promise.resolve(null),
      precisaDadosComp ? obterCatalogoDadosComplementaresViewer(ctx) : Promise.resolve(null),
      precisaLocExtra ? obterCatalogoLocalizadoresExtraViewer(ctx) : Promise.resolve(null)
    ]);

    const detalhado = precisaQualquerCatalogo
      ? parseDetalhesPreferenciaMinutaHtml(htmlResp, prefItem, ctx, {
        classificacoes,
        eventosComp,
        prepararMov,
        prepararMovRemessa,
        eventosEncadeadosT,
        eventosEncadeadosR,
        dadosCompCatalogo,
        localizadoresExtras
      })
      : preParsed;

    cacheMap.set(prefItem.id, detalhado);
    return detalhado;
  }

  function dividirIdsDelimViewer(raw) {
    if (!raw) return [];
    if (Array.isArray(raw)) return raw.map(v => String(v || '').trim()).filter(v => v && v !== 'null');
    return String(raw).split(/[,;#|]+/).map(s => s.trim()).filter(s => s && s !== 'null');
  }

  function obterCamposPersonalizadosMesclados(html) {
    const o1 = extrairObjetoJsJson(html, 'camposPersonalizados');
    const o2 = extrairObjetoJsJson(html, 'camposPersonalizadosOrdem');
    const camposP = {
      ...(o1 && !Array.isArray(o1) ? o1 : {}),
      ...(o2 && !Array.isArray(o2) ? o2 : {})
    };
    const rawAg = camposP.Agendamento
      ? decodificarComponenteQuerySeguro(camposP.Agendamento)
      : (camposP.frmDadosMinutaParaATP ? decodificarBase64QuerySeguro(camposP.frmDadosMinutaParaATP) : '');
    return {
      camposP,
      agQuery: parseQueryStringSegura(rawAg)
    };
  }

  function construirMapaComportamentosPadrao(mapaInicial) {
    const mapa = new Map(mapaInicial || []);
    if (!mapa.has('0')) mapa.set('0', 'Remover o processo do(s) localizador(es) informado(s)');
    if (!mapa.has('1')) mapa.set('1', 'Remover o processo de TODOS localizadores');
    if (!mapa.has('2')) mapa.set('2', 'Remover o processo de TODOS localizadores, EXCETO os de sistema');
    if (!mapa.has('3')) mapa.set('3', 'NÃO remover o processo de localizador algum (apenas acrescentar o indicado)');
    if (!mapa.has('5')) mapa.set('5', 'Apenas substituir o localizador PRINCIPAL pelo indicado');
    return mapa;
  }

  function extrairIdsNumLocalizadorDesativar(camposP) {
    if (!camposP || typeof camposP !== 'object') return [];
    const chaves = Object.keys(camposP)
      .filter(k => /^NumIdLocalizadorDesativar\d*$/i.test(k))
      .sort((a, b) => {
        const na = parseInt(a.replace(/\D/g, '') || '0', 10);
        const nb = parseInt(b.replace(/\D/g, '') || '0', 10);
        return na - nb;
      });
    const out = [];
    chaves.forEach(k => {
      dividirIdsDelimViewer(camposP[k]).forEach(id => {
        if (!out.includes(id)) out.push(id);
      });
    });
    return out;
  }

  function obterSelecaoMultiplaEprocDom(docResp, html, selectId, camposP = null) {
    const out = [];
    const add = (v) => {
      const s = String(v || '').trim();
      if (s && s !== 'null' && !out.includes(s)) out.push(s);
    };
    obterValoresSelecionadosSelect(docResp, selectId).forEach(add);
    if (docResp) {
      docResp.querySelectorAll(`li.selected input[name="selectItem${selectId}[]"], input[name="selectItem${selectId}[]"]:checked, input[name="selectItem${selectId}[]"][checked]`).forEach(inp => {
        add(inp.value || inp.getAttribute('value'));
      });
    }
    if (camposP && camposP[selectId] !== undefined && camposP[selectId] !== null) {
      dividirIdsDelimViewer(camposP[selectId]).forEach(add);
    }
    if (html) {
      const reMs = new RegExp(`#${selectId}['"]?\\s*\\)\\s*\\.(?:multipleSelect\\(\\s*['"]setSelects['"]\\s*,|val\\()\\s*(\\[[^\\]]*\\])`, 'gi');
      let m;
      while ((m = reMs.exec(html)) !== null) {
        try {
          const arr = JSON.parse(m[1].replace(/'/g, '"'));
          if (Array.isArray(arr)) arr.forEach(add);
        } catch (e) {}
      }
    }
    return out;
  }

  function extrairMetadadosBasicosPrefViewer(docResp, prefItem, agQuery, camposP, mapaGrupos) {
    const radioTipoChecked = docResp
      ? docResp.querySelector('input[name="rdPrefTipo"][checked], input[name="rdPrefTipo"]:checked')
      : null;
    const rawTipo = (agQuery && agQuery.get('rdPrefTipo'))
      || (camposP && (camposP.rdPrefTipo || camposP.sinTipo))
      || (radioTipoChecked ? radioTipoChecked.value : '')
      || (prefItem.complemento ? prefItem.complemento.split(';')[0] : '');
    const tipo = rawTipo === 'U' ? 'Unidade' : (rawTipo === 'I' ? 'Individual' : (prefItem.tipo || ''));

    const chkPad = docResp ? docResp.getElementById('chkValorPadrao') : null;
    const flagPadrao = (camposP && camposP.chkValorPadrao)
      || (chkPad && (chkPad.checked || chkPad.hasAttribute('checked')) ? 'S' : '')
      || (prefItem.complemento ? prefItem.complemento.split(';')[2] : '');
    const padrao = prefItem.padrao || (flagPadrao === 'S' ? 'Sim' : (flagPadrao === 'N' ? 'Não' : ''));

    const grupoSelIds = docResp ? obterValoresSelecionadosSelect(docResp, 'selFormularioPersonalizacaoGrupo') : [];
    const grupoId = (agQuery && agQuery.get('selFormularioPersonalizacaoGrupo'))
      || (camposP && (camposP.selGrupo || camposP.selFormularioPersonalizacaoGrupo))
      || grupoSelIds[0]
      || '';
    const grupo = (grupoId && grupoId !== 'null' ? (mapaGrupos && mapaGrupos.get(grupoId)) || '' : '') || prefItem.grupo || '';

    const chkMovPref = docResp ? docResp.getElementById('chkMovPreferencial') : null;
    const chkPainel = docResp ? docResp.getElementById('chkPainelInicial') : null;
    const movPrefFlag = (agQuery && agQuery.get('chkMovPreferencial'))
      || (camposP && (camposP.chkMovPreferencial || camposP.sinExibirPainel))
      || ((chkMovPref && (chkMovPref.checked || chkMovPref.hasAttribute('checked'))) ? 'S' : '')
      || ((chkPainel && (chkPainel.checked || chkPainel.hasAttribute('checked'))) ? 'S' : '')
      || (prefItem.complemento ? prefItem.complemento.split(';')[4] : '');
    const acaoPreferencial = prefItem.acaoPreferencial || prefItem.painelInicial || (movPrefFlag === 'S' ? 'Sim' : 'Não');

    return { tipo, padrao, grupo, acaoPreferencial };
  }

  async function executarPostPreferenciaClassica(prefItem, ctx) {
    const pairs = [
      ...((ctx && ctx.formInfo && ctx.formInfo.basePairs) || []),
      ['hdnAcaoPreferencia', ''],
      ['hdnPreferencia', prefItem.id],
      ['txtPreferencia', prefItem.nome],
      ['hdnPreferenciaUsuario', prefItem.complemento || ''],
      ['hdnNumIdValorSelecionadoCombo', prefItem.id],
      ['hdnStrDescricaoPreferencia', prefItem.nome],
      ['hdnStrPreferenciaUsuario', prefItem.complemento || ''],
      ['isChangePreferencia', '1']
    ];
    const resp = await fetch(ctx.formInfo.actionUrl, {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: encodeWindows1252Body(pairs),
      credentials: 'same-origin'
    });
    if (!resp.ok) {
      throw new Error(`HTTP ${resp.status} ao carregar preferência "${prefItem.nome}"`);
    }
    return lerRespostaTexto(resp);
  }

  // -------------------- MÓDULO 3: MOVIMENTAÇÕES --------------------
  async function obterContextoMovimentacaoVisualizador() {
    return obterContextoTelaClassicaViewer({
      formId: 'frmProcessoLista',
      acaoMenu: 'processo_movimento_consultar',
      nomeAcao: 'processo_movimento_consultar',
      nomeTela: 'Movimentação Processual',
      exigeProcessoNoMenu: true,
      verificaDocNaTela: (doc) => Boolean(doc && doc.getElementById('frmProcessoLista') && (doc.getElementById('txtEvento') || doc.getElementById('hdnEvento'))),
      selectsExtras: ['selRemeteVaraOrigem', 'selOrgao', 'selIdSigilo_Padrao'],
      motivoIndisponivel: 'Para visualizar as preferências de Movimentação, acesse a tela Movimentação Processual de um processo no eproc 2G.'
    });
  }

  function parseDetalhesPreferenciaMovimentacaoHtml(htmlResp, prefItem, ctxBase, catalogosExtras = {}) {
    const html = htmlResp || '';
    const docResp = new DOMParser().parseFromString(html, 'text/html');
    const baseCat = (ctxBase && (ctxBase.catalogosBasicos || (ctxBase.formInfo && ctxBase.formInfo.catalogosBasicos))) || {};
    const { camposP, agQuery } = obterCamposPersonalizadosMesclados(html);

    const mapaGlobalLocsMov = (typeof obterMapaNomeLocalizadoresGlobal === 'function')
      ? obterMapaNomeLocalizadoresGlobal(docResp, html)
      : new Map();
    const mapaLocs = mesclarMapasStrings(
      construirMapaSelectOptions(docResp, 'selNovoLocalizador'),
      mesclarMapasStrings(
        construirMapaSelectOptions(docResp, 'selLocalizadorSecundario'),
        mesclarMapasStrings(
          construirMapaSelectOptions(docResp, 'selLocalizadorDesativar'),
          mesclarMapasStrings(
            mapaGlobalLocsMov,
            mesclarMapasStrings(catalogosExtras.localizadoresExtras, baseCat.localizadores)
          )
        )
      )
    );
    const mapaComport = construirMapaComportamentosPadrao(
      mesclarMapasStrings(construirMapaSelectOptions(docResp, 'selOpcaoLocalizador'), baseCat.comportamentos)
    );
    const mapaGrupos = mesclarMapasStrings(construirMapaSelectOptions(docResp, 'selFormularioPersonalizacaoGrupo'), baseCat.grupos);
    const meta = extrairMetadadosBasicosPrefViewer(docResp, prefItem, agQuery, camposP, mapaGrupos);

    const radioLocChecked = docResp.querySelector('input[name="rdPrefLocalizadores"][checked], input[name="rdPrefLocalizadores"]:checked');
    const rdLoc = agQuery.get('rdPrefLocalizadores')
      || extrairLiteralJsString(html, 'mc_strRdPrefLocalizadores')
      || String(camposP.sinLocalizadores || '')
      || (radioLocChecked ? radioLocChecked.value : '');
    const mapModoLoc = { L: 'Localizadores selecionados', M: 'Marcar todos atuais', D: 'Desmarcar todos atuais' };
    const modoLocalizadores = mapModoLoc[rdLoc] || rdLoc || '';

    const comportIds = obterValoresSelecionadosSelect(docResp, 'selOpcaoLocalizador');
    const comportCod = agQuery.get('selOpcaoLocalizador') !== null
      ? agQuery.get('selOpcaoLocalizador')
      : (camposP.selOpcaoLocalizador !== undefined ? String(camposP.selOpcaoLocalizador) : (comportIds[0] || ''));
    const comportamentoLocalizador = (comportCod !== '' && comportCod !== 'null') ? (mapaComport.get(comportCod) || `Código ${comportCod}`) : '';

    const locPrincIds = obterValoresSelecionadosSelect(docResp, 'selNovoLocalizador');
    const locPrincId = agQuery.get('selNovoLocalizador')
      || String(camposP.IdNovoLocalizador || camposP.selNovoLocalizador || '')
      || locPrincIds[0]
      || '';
    const localizadorPrincipal = (locPrincId && locPrincId !== 'null') ? (mapaLocs.get(locPrincId) || `ID: ${locPrincId}`) : '';

    const locSecIds = [
      ...obterValoresSelecionadosSelect(docResp, 'selLocalizadorSecundario'),
      ...agQuery.getAll('selLocalizadorSecundario[]'),
      ...dividirIdsDelimViewer(camposP.selLocalizadorSecundario)
    ];
    const localizadoresSecundarios = resolverIdsParaTextos(locSecIds, mapaLocs);

    const mcLocDesRaw = extrairLiteralJsString(html, 'mc_selLocalizadorDesativar');
    const locDesIds = [
      ...dividirIdsDelimViewer(mcLocDesRaw),
      ...obterValoresSelecionadosSelect(docResp, 'selLocalizadorDesativar'),
      ...agQuery.getAll('selLocalizadorDesativar[]'),
      ...extrairIdsNumLocalizadorDesativar(camposP)
    ];
    const localizadoresRemover = resolverIdsParaTextos(locDesIds, mapaLocs);

    const inpTxtEv = docResp.getElementById('txtEvento');
    const inpHdnEv = docResp.getElementById('hdnEvento');
    const eventoNome = extrairLiteralJsString(html, 'mc_txtEvento')
      || agQuery.get('txtEvento')
      || String(camposP.txtEvento || '')
      || (inpTxtEv ? (inpTxtEv.value || inpTxtEv.getAttribute('value') || '') : '');
    const eventoCod = extrairLiteralJsString(html, 'mc_hdnEvento')
      || agQuery.get('hdnEvento')
      || String(camposP.hdnEvento || '')
      || (inpHdnEv ? (inpHdnEv.value || inpHdnEv.getAttribute('value') || '') : '');

    const mcEvCompRaw = extrairLiteralJsString(html, 'mc_hdnEventosComplementares');
    const evCompIds = [
      ...dividirIdsDelimViewer(mcEvCompRaw),
      ...agQuery.getAll('selEventoComplementar[]'),
      ...obterValoresSelecionadosSelect(docResp, 'selEventoComplementar'),
      ...dividirIdsDelimViewer(camposP.selEventoComplementar)
    ];
    const mapaEvComp = mesclarMapasStrings(construirMapaSelectOptions(docResp, 'selEventoComplementar'), catalogosExtras.eventosComp);
    const eventosComplementares = resolverIdsParaTextos(evCompIds, mapaEvComp);

    const mcDadosComp = extrairLiteralJsString(html, 'mc_strDadosComplementares');
    const hdnDadosCompEl = docResp.getElementById('hdnDadosComplementares');
    const docHdnDadosComp = hdnDadosCompEl ? (hdnDadosCompEl.value || hdnDadosCompEl.getAttribute('value') || '').trim() : '';
    const rawDadosComp = mcDadosComp || agQuery.get('hdnDadosComplementares') || String(camposP.hdnDadosComplementares || '') || docHdnDadosComp || '';
    const descDadosEl = docResp.getElementById('descDadosComplementares');
    const descDadosDom = descDadosEl ? decodificarEntidadesHtml(decodeEntities(descDadosEl.textContent || '')).replace(/\s+/g, ' ').trim() : '';
    const dadosComplementares = formatarDadosComplementaresMinuta(rawDadosComp, agQuery, {
      descDadosDom,
      descDadosPrepMov: catalogosExtras.prepararMov ? catalogosExtras.prepararMov.descDadosComplementares : '',
      dadosCompSelects: catalogosExtras.prepararMov ? catalogosExtras.prepararMov.dadosCompSelects : null,
      dadosCompCatalogo: catalogosExtras.dadosCompCatalogo || null
    });

    const phpEncadeado = parsePhpSerializedAssoc(extrairLiteralJsString(html, 'mc_arrDadosEventoEncadeado'));
    const arrPrefIntimacao = extrairObjetoJsJson(html, 'arrPrefIntimacaoCitacao') || [];
    const prepMov = catalogosExtras.prepararMov || {};
    const prepMovRemessa = catalogosExtras.prepararMovRemessa || {};

    const selOrgaoDom = obterValoresSelecionadosSelect(docResp, 'selOrgao');
    const orgaoId = String(camposP.IdOrgao || '').trim()
      || agQuery.get('selOrgao')
      || extrairLiteralJsString(html, 'mc_selOrgao')
      || selOrgaoDom[0]
      || '';
    const mapaOrgaos = mesclarMapasStrings(
      construirMapaSelectOptions(docResp, 'selOrgao'),
      mesclarMapasStrings(baseCat.selOrgao, mesclarMapasStrings(prepMovRemessa.orgaos, prepMov.orgaos))
    );
    const orgao = (orgaoId && orgaoId !== 'null') ? (mapaOrgaos.get(orgaoId) || `ID: ${orgaoId}`) : '';

    const remVaraDom = obterValoresSelecionadosSelect(docResp, 'selRemeteVaraOrigem');
    const remVaraCod = String(camposP.selRemeteVaraOrigem || agQuery.get('selRemeteVaraOrigem') || remVaraDom[0] || '').trim().toUpperCase();
    const remeterVaraOrigem = remVaraCod === 'S' ? 'Sim' : (remVaraCod === 'N' ? 'Não' : '');

    const evIntId = agQuery.get('selEventoEncadeadoCitacaoIntimacao')
      || agQuery.get('hdnEventoCitacaoIntimacao')
      || phpEncadeado.IdEventoCitacaoIntimacao
      || (camposP.selEventoEncadeadoCitacaoIntimacao && camposP.selEventoEncadeadoCitacaoIntimacao !== 'null' ? String(camposP.selEventoEncadeadoCitacaoIntimacao).trim() : '')
      || (arrPrefIntimacao[0] && arrPrefIntimacao[0].evento ? String(arrPrefIntimacao[0].evento.idEvento || '') : '')
      || '';
    const flagInt = agQuery.get('chkEncadeamentoIntimar') || phpEncadeado.chkEncadeamentoIntimar || extrairLiteralJsString(html, 'mc_chkEncadeamentoIntimar') || String(camposP.chkEncadeamentoIntimar || camposP.chkIntimarAutomatico || '');
    const deveIntimar = flagInt === '1' || flagInt === 'S' || flagInt === 'on' || (!!evIntId && evIntId !== 'null') || arrPrefIntimacao.length > 0;
    const mapaEvInt = mesclarMapasStrings(
      construirMapaSelectOptions(docResp, 'selEventoEncadeadoCitacaoIntimacao'),
      mesclarMapasStrings(catalogosExtras.eventosEncadeadosT, prepMov.eventosIntimacao)
    );
    const eventoIntimacao = (deveIntimar && evIntId && evIntId !== 'null') ? (mapaEvInt.get(evIntId) || `Cód. ${evIntId}`) : '';
    const prazosIntimacao = deveIntimar ? formatarPrazosIntimacaoMinuta(agQuery, arrPrefIntimacao, camposP) : '';

    const evRemId = agQuery.get('selEventoEncadeadoRemessa') || phpEncadeado.IdEventoRemessa || String(camposP.selEventoEncadeadoRemessa || '');
    const orgRemId = phpEncadeado.IdOrgaoDestino || (!orgao ? orgaoId : '') || '';
    const flagRem = agQuery.get('chkEncadeamentoRemessa') || phpEncadeado.chkEncadeamentoRemessa || String(camposP.chkEncadeamentoRemessa || '');
    const deveRemeter = flagRem === '1' || flagRem === 'S' || flagRem === 'on' || (!!evRemId && evRemId !== 'null');
    const mapaEvRem = mesclarMapasStrings(
      construirMapaSelectOptions(docResp, 'selEventoEncadeadoRemessa'),
      mesclarMapasStrings(catalogosExtras.eventosEncadeadosR, prepMov.eventosRemessa)
    );
    const eventoRemessa = (deveRemeter && evRemId && evRemId !== 'null') ? (mapaEvRem.get(evRemId) || `ID: ${evRemId}`) : '';
    const orgaoRemessa = (deveRemeter && orgRemId && orgRemId !== 'null') ? (mapaOrgaos.get(orgRemId) || `ID: ${orgRemId}`) : '';

    const chkAnexosDom = docResp.getElementById('chkSalvarAnexos');
    const flagAnexos = String(camposP.chkSalvarAnexos || ((chkAnexosDom && (chkAnexosDom.checked || chkAnexosDom.hasAttribute('checked'))) ? 'S' : ''));
    const salvarAnexos = flagAnexos === 'S' ? 'Sim' : 'Não';

    const extras = [];
    const diasSusp = extrairLiteralJsString(html, 'mc_txtNumDiasSuspensao') || String(camposP.txtNumDiasSuspensao || '');
    const dtfSusp = extrairLiteralJsString(html, 'mc_txtDtfSuspensao') || String(camposP.txtDtfSuspensao || '');
    if (diasSusp || dtfSusp) extras.push(`Suspensão: ${[diasSusp ? `${diasSusp}d` : '', dtfSusp].filter(Boolean).join(' até ')}`);
    const diasTD = String(camposP.txtNumDiasTramitacaoDireta || '');
    if (diasTD) extras.push(`Tramitação direta: ${diasTD}d`);
    const espAto = extrairLiteralJsString(html, 'mc_strAtoOrdinatorioDesignarPericiaEspecialidade') || String(camposP.strAtoOrdinatorioDesignarPericiaEspecialidade || '');
    if (espAto && espAto !== 'null') extras.push(`Especialidade: ${espAto}`);
    const descModelo = extrairLiteralJsString(html, 'mc_strDescricaoModeloMatriz') || extrairLiteralJsString(html, 'mc_strModeloPadrao');
    if (descModelo) extras.push(`Modelo: ${descModelo}`);
    if (String(camposP.chkIntimarAutomatico || '') === 'S') extras.push('Intimar automático');

    return {
      ...prefItem,
      detalhado: true,
      erroDetalhe: '',
      ...meta,
      modoLocalizadores,
      comportamentoLocalizador,
      localizadorPrincipal,
      localizadoresSecundarios,
      localizadoresRemover,
      eventoNome,
      eventoCod,
      eventosComplementares,
      dadosComplementares,
      _rawDadosComp: rawDadosComp,
      _temDescDadosDom: Boolean(descDadosDom),
      orgao,
      remeterVaraOrigem,
      intimarPartes: deveIntimar ? 'Sim' : 'Não',
      eventoIntimacao,
      prazosIntimacao,
      remeterProcesso: deveRemeter ? 'Sim' : 'Não',
      eventoRemessa,
      orgaoRemessa,
      salvarAnexos,
      _orgId: orgaoId,
      _evRemId: (evRemId && evRemId !== 'null') ? evRemId : '',
      opcoesExtras: extras.join(' | ')
    };
  }

  async function carregarDetalhesPreferenciaMovimentacao(prefItem, ctx, options = {}) {
    const cacheMap = obterCacheDetalhesModuloViewer('movimentacoes');
    if (!options.forcarRecarga && cacheMap.has(prefItem.id)) {
      return cacheMap.get(prefItem.id);
    }

    const htmlResp = await executarPostPreferenciaClassica(prefItem, ctx);
    const preParsed = parseDetalhesPreferenciaMovimentacaoHtml(htmlResp, prefItem, ctx, {});
    const precisaComp = (preParsed.eventosComplementares || []).some(c => /^ID:\s*\d+$/.test(c));
    const precisaDadosComp = Boolean(preParsed.dadosComplementares && /DadoComplementar|Dado #/i.test(preParsed.dadosComplementares))
      || Boolean(preParsed._rawDadosComp && !preParsed._temDescDadosDom);
    const precisaOrgao = /^ID:\s*/.test(preParsed.orgao || '');
    const precisaEncInt = preParsed.intimarPartes === 'Sim' && (!preParsed.eventoIntimacao || /^Cód\./.test(preParsed.eventoIntimacao));
    const precisaEncRem = preParsed.remeterProcesso === 'Sim' && Boolean(preParsed._evRemId) && (!preParsed.eventoRemessa || /^ID:/.test(preParsed.eventoRemessa));
    const precisaOrgRem = preParsed.remeterProcesso === 'Sim' && Boolean(preParsed._evRemId) && /^ID:/.test(preParsed.orgaoRemessa || '');
    const precisaLocExtra = [
      preParsed.localizadorPrincipal,
      ...(preParsed.localizadoresSecundarios || []),
      ...(preParsed.localizadoresRemover || [])
    ].some(v => typeof v === 'string' && /^ID:\s*/.test(v));
    const precisaPrepMovMain = (precisaDadosComp || precisaOrgao || precisaEncInt || precisaEncRem || precisaOrgRem) && Boolean(preParsed.eventoCod);

    const [
      eventosComp,
      prepararMov,
      prepararMovRemessa,
      eventosEncadeadosT,
      eventosEncadeadosR,
      dadosCompCatalogo,
      localizadoresExtras
    ] = await Promise.all([
      (precisaComp && preParsed.eventoCod) ? obterCatalogoEventosCompViewer(preParsed.eventoCod, ctx) : Promise.resolve(null),
      precisaPrepMovMain ? obterCatalogoPrepararMovViewer(preParsed.eventoCod, ctx, preParsed._rawDadosComp || '', { precisaDadosComp }) : Promise.resolve(null),
      (precisaOrgRem && preParsed._evRemId && preParsed._evRemId !== preParsed.eventoCod) ? obterCatalogoPrepararMovViewer(preParsed._evRemId, ctx) : Promise.resolve(null),
      precisaEncInt ? obterCatalogoEncadeadoViewer('T', ctx) : Promise.resolve(null),
      precisaEncRem ? obterCatalogoEncadeadoViewer('R', ctx) : Promise.resolve(null),
      precisaDadosComp ? obterCatalogoDadosComplementaresViewer(ctx) : Promise.resolve(null),
      precisaLocExtra ? obterCatalogoLocalizadoresExtraViewer(ctx) : Promise.resolve(null)
    ]);

    const precisaQualquer = precisaComp || precisaDadosComp || precisaOrgao || precisaEncInt || precisaEncRem || precisaOrgRem || precisaLocExtra;
    const detalhado = precisaQualquer
      ? parseDetalhesPreferenciaMovimentacaoHtml(htmlResp, prefItem, ctx, {
        eventosComp,
        prepararMov,
        prepararMovRemessa,
        eventosEncadeadosT,
        eventosEncadeadosR,
        dadosCompCatalogo,
        localizadoresExtras
      })
      : preParsed;

    cacheMap.set(prefItem.id, detalhado);
    return detalhado;
  }

  // -------------------- MÓDULO 5: INTIMAÇÕES --------------------
  async function obterContextoIntimacaoVisualizador() {
    return obterContextoTelaClassicaViewer({
      formId: 'frmProcessoCitacao',
      acaoMenu: 'processo_intimacao_bloco',
      acaoMenuAlt: 'processo_intimacao',
      acaoPattern: 'processo_intimacao',
      nomeAcao: 'processo_intimacao_bloco',
      nomeTela: 'Intimação Eletrônica',
      exigeProcessoNoMenu: true,
      selectsExtras: ['selEventoJudicial', 'selFiltroPartes'],
      motivoIndisponivel: 'Para visualizar as preferências de Intimação, acesse a tela de Intimação Eletrônica de um processo (ou em bloco) no eproc 2G.'
    });
  }

  function parseDetalhesPreferenciaIntimacaoHtml(htmlResp, prefItem, ctxBase, catalogosExtras = {}) {
    const html = htmlResp || '';
    const docResp = new DOMParser().parseFromString(html, 'text/html');
    const baseCat = (ctxBase && (ctxBase.catalogosBasicos || (ctxBase.formInfo && ctxBase.formInfo.catalogosBasicos))) || {};
    const { camposP, agQuery } = obterCamposPersonalizadosMesclados(html);
    const arrPrefInt = extrairObjetoJsJson(html, 'arrPrefIntimacaoCitacao') || [];

    const mapaGlobalLocsMov = (typeof obterMapaNomeLocalizadoresGlobal === 'function')
      ? obterMapaNomeLocalizadoresGlobal(docResp, html)
      : new Map();
    const mapaLocs = mesclarMapasStrings(
      construirMapaSelectOptions(docResp, 'selNovoLocalizador'),
      mesclarMapasStrings(
        construirMapaSelectOptions(docResp, 'selLocalizadorSecundario'),
        mesclarMapasStrings(
          construirMapaSelectOptions(docResp, 'selLocalizadorDesativar'),
          mesclarMapasStrings(
            mapaGlobalLocsMov,
            mesclarMapasStrings(catalogosExtras.localizadoresExtras, baseCat.localizadores)
          )
        )
      )
    );
    const mapaComport = construirMapaComportamentosPadrao(
      mesclarMapasStrings(construirMapaSelectOptions(docResp, 'selOpcaoLocalizador'), baseCat.comportamentos)
    );
    const mapaGrupos = mesclarMapasStrings(construirMapaSelectOptions(docResp, 'selFormularioPersonalizacaoGrupo'), baseCat.grupos);
    const mapaEventos = mesclarMapasStrings(construirMapaSelectOptions(docResp, 'selEventoJudicial'), baseCat.selEventoJudicial);
    const mapaFiltroPartes = mesclarMapasStrings(construirMapaSelectOptions(docResp, 'selFiltroPartes'), baseCat.selFiltroPartes);
    const meta = extrairMetadadosBasicosPrefViewer(docResp, prefItem, agQuery, camposP, mapaGrupos);

    const evSelDom = obterValoresSelecionadosSelect(docResp, 'selEventoJudicial');
    const eventoCod = String(camposP.IdEventoJudicial || camposP.selEventoJudicial || agQuery.get('selEventoJudicial') || evSelDom[0] || '').trim();
    const eventoNome = (eventoCod && eventoCod !== 'null') ? (mapaEventos.get(eventoCod) || `Evento ${eventoCod}`) : '';

    const lerCampoInt = (k) => {
      if (camposP && camposP[k] !== undefined && camposP[k] !== null) {
        const s = String(camposP[k]).trim();
        if (s && s !== 'null' && s !== 'N') return s;
      }
      if (agQuery && agQuery.get(k)) return String(agQuery.get(k)).trim();
      const inp = docResp.getElementById(k);
      if (inp) {
        if (inp.type === 'checkbox' || inp.type === 'radio') {
          return (inp.checked || inp.hasAttribute('checked')) ? 'S' : '';
        }
        const v = String(inp.value || inp.getAttribute('value') || '').trim();
        if (v) return v;
      }
      return '';
    };

    const formPrazo = (k) => {
      const v = lerCampoInt(k);
      if (!v) return '';
      return /^\d+$/.test(v) ? `${v}d` : v;
    };

    const rdOpPolo = docResp.getElementById('porPolo');
    const rdOpTipo = docResp.getElementById('porTipoDeParte');
    const rdOpIgual = docResp.getElementById('igual');
    let opAv = lerCampoInt('opcoes_avancadas');
    if (!opAv && rdOpPolo && (rdOpPolo.checked || rdOpPolo.hasAttribute('checked'))) opAv = 'porPolo';
    if (!opAv && rdOpTipo && (rdOpTipo.checked || rdOpTipo.hasAttribute('checked'))) opAv = 'porTipoDeParte';
    if (!opAv && rdOpIgual && (rdOpIgual.checked || rdOpIgual.hasAttribute('checked'))) opAv = 'igual';
    const mapModos = {
      porPolo: 'Por polo',
      porTipoDeParte: 'Por tipo de parte',
      porTipoParte: 'Por tipo de parte',
      igual: 'Mesmo prazo',
      porEntidade: 'Por entidade'
    };
    const modoPrazos = opAv ? (mapModos[opAv] || opAv) : '';

    const prazoEspEnt = formPrazo('txtPrazoEntPrazoEspecial');
    const prazoSimpEnt = formPrazo('txtPrazoEntPrazoSimples');
    const prazoSimpDemais = formPrazo('txtPrazoNaoEntPrazoSimples');
    const prazoDPU = formPrazo('txtPrazoDPU');
    const prazoAutores = formPrazo('txtPrazoAutores');
    const prazoReus = formPrazo('txtPrazoReus');
    const prazoInteressados = formPrazo('txtPrazoInteressados');
    const prazoMP = formPrazo('txtPrazoMPF');

    const textoPrazosCheck = formatarPrazosIntimacaoMinuta(agQuery, arrPrefInt, camposP);
    const temUrgDom = (() => {
      const el = docResp.getElementById('chkIntimacaoUrgente');
      if (el && (el.checked || el.hasAttribute('checked'))) return true;
      return Object.entries(camposP).some(([k, v]) => /Urgente/i.test(k) && ['S', '1', 'on', 'true'].includes(String(v)));
    })();
    const urgente = (temUrgDom || /\bUrgente\b/.test(textoPrazosCheck)) ? 'Sim' : 'Não';

    const flagEnc = lerCampoInt('chkEncadeamentoIntimar');
    const evEncId = lerCampoInt('selEventoEncadeadoCitacaoIntimacao');
    const encadeamentoIntimacao = (flagEnc === 'S' || flagEnc === '1' || flagEnc === 'on' || (!!evEncId && evEncId !== 'null')) ? 'Sim' : 'Não';
    const mapaEvInt = mesclarMapasStrings(construirMapaSelectOptions(docResp, 'selEventoEncadeadoCitacaoIntimacao'), catalogosExtras.eventosEncadeadosT);
    const eventoEncadeadoIntimacao = (encadeamentoIntimacao === 'Sim' && evEncId && evEncId !== 'null')
      ? (mapaEvInt.get(evEncId) || `Cód. ${evEncId}`)
      : '';

    const radioLocChecked = docResp.querySelector('input[name="rdPrefLocalizadores"][checked], input[name="rdPrefLocalizadores"]:checked');
    const rdLoc = lerCampoInt('sinLocalizadores')
      || agQuery.get('rdPrefLocalizadores')
      || extrairLiteralJsString(html, 'mc_strRdPrefLocalizadores')
      || (radioLocChecked ? radioLocChecked.value : '');
    const mapModoLoc = { L: 'Localizadores selecionados', M: 'Marcar todos atuais', D: 'Desmarcar todos atuais' };
    const modoLocalizadores = mapModoLoc[rdLoc] || rdLoc || '';

    const comportIds = obterValoresSelecionadosSelect(docResp, 'selOpcaoLocalizador');
    const comportCod = lerCampoInt('selOpcaoLocalizador') || (comportIds[0] || '');
    const comportamentoLocalizador = (comportCod !== '' && comportCod !== 'null') ? (mapaComport.get(comportCod) || `Código ${comportCod}`) : '';

    const locPrincDom = obterValoresSelecionadosSelect(docResp, 'selNovoLocalizador');
    const locPrincId = lerCampoInt('IdNovoLocalizador') || lerCampoInt('selNovoLocalizador') || locPrincDom[0] || '';
    const localizadorPrincipal = (locPrincId && locPrincId !== 'null') ? (mapaLocs.get(locPrincId) || `ID: ${locPrincId}`) : '';

    const locSecIds = [
      ...obterValoresSelecionadosSelect(docResp, 'selLocalizadorSecundario'),
      ...dividirIdsDelimViewer(camposP.selLocalizadorSecundario)
    ];
    const localizadoresSecundarios = resolverIdsParaTextos(locSecIds, mapaLocs);

    const locDesIds = [
      ...dividirIdsDelimViewer(extrairLiteralJsString(html, 'mc_selLocalizadorDesativar')),
      ...obterValoresSelecionadosSelect(docResp, 'selLocalizadorDesativar'),
      ...extrairIdsNumLocalizadorDesativar(camposP)
    ];
    const localizadoresRemover = resolverIdsParaTextos(locDesIds, mapaLocs);

    const fpDom = obterValoresSelecionadosSelect(docResp, 'selFiltroPartes');
    const fpId = lerCampoInt('IdFiltroPartes') || fpDom[0] || '';
    const filtroPartes = (fpId && fpId !== 'null') ? (mapaFiltroPartes.get(fpId) || `Cód. ${fpId}`) : '';

    const extras = [];
    const pzIgual = formPrazo('txtPrazoIgual');
    if (pzIgual) extras.push(`Prazo igual: ${pzIgual}`);
    const dtIgual = lerCampoInt('txtDataIgual');
    if (dtIgual) extras.push(`Data igual: ${dtIgual}`);
    if (lerCampoInt('chkEncadeamentoMarcarIntimacao') === 'S') extras.push('Marcar intimação automático');
    if (lerCampoInt('chkSelEventoDocumentoIntimacao') === 'S') extras.push('Gerar documento intimação');

    return {
      ...prefItem,
      detalhado: true,
      erroDetalhe: '',
      ...meta,
      eventoNome,
      eventoCod: (eventoCod && eventoCod !== 'null') ? eventoCod : '',
      modoPrazos,
      prazoEspEnt,
      prazoSimpEnt,
      prazoSimpDemais,
      prazoDPU,
      prazoAutores,
      prazoReus,
      prazoInteressados,
      prazoMP,
      urgente,
      encadeamentoIntimacao,
      eventoEncadeadoIntimacao,
      modoLocalizadores,
      comportamentoLocalizador,
      localizadorPrincipal,
      localizadoresSecundarios,
      localizadoresRemover,
      filtroPartes,
      opcoesExtras: extras.join(' | ')
    };
  }

  async function carregarDetalhesPreferenciaIntimacao(prefItem, ctx, options = {}) {
    const cacheMap = obterCacheDetalhesModuloViewer('intimacoes');
    if (!options.forcarRecarga && cacheMap.has(prefItem.id)) {
      return cacheMap.get(prefItem.id);
    }

    const htmlResp = await executarPostPreferenciaClassica(prefItem, ctx);
    const preParsed = parseDetalhesPreferenciaIntimacaoHtml(htmlResp, prefItem, ctx, {});
    const precisaLocExtra = [
      preParsed.localizadorPrincipal,
      ...(preParsed.localizadoresSecundarios || []),
      ...(preParsed.localizadoresRemover || [])
    ].some(v => typeof v === 'string' && /^ID:\s*/.test(v));
    const precisaEncT = preParsed.encadeamentoIntimacao === 'Sim' && /^Cód\./.test(preParsed.eventoEncadeadoIntimacao || '');

    const [localizadoresExtras, eventosEncadeadosT] = await Promise.all([
      precisaLocExtra ? obterCatalogoLocalizadoresExtraViewer(ctx) : Promise.resolve(null),
      precisaEncT ? obterCatalogoEncadeadoViewer('T', ctx) : Promise.resolve(null)
    ]);

    const detalhado = (precisaLocExtra || precisaEncT)
      ? parseDetalhesPreferenciaIntimacaoHtml(htmlResp, prefItem, ctx, { localizadoresExtras, eventosEncadeadosT })
      : preParsed;

    cacheMap.set(prefItem.id, detalhado);
    return detalhado;
  }

  // -------------------- MÓDULO 4: ÁREA DE MINUTAS (DOCUMENTOS) --------------------
  async function obterContextoAreaMinutasVisualizador() {
    return obterContextoTelaClassicaViewer({
      formId: 'frmMinutaLista',
      acaoMenu: 'minuta_area_trabalho',
      nomeAcao: 'minuta_area_trabalho',
      nomeTela: 'Área de Trabalho de Minutas',
      exigeProcessoNoMenu: false,
      selectsExtras: [
        'selTipoDocumento', 'selStatusMinuta', 'selLocalizador', 'selUsuarioCriador',
        'selClasseJudicial', 'selCompetencia', 'selJuizo', 'selStatusProcesso',
        'selDadoComplementar', 'selSigiloMinuta', 'selSigiloProcesso',
        'selTipoPaginacao', 'selRecursoHistoricoMinuta'
      ],
      motivoIndisponivel: 'Para visualizar as preferências de Documentos, abra a tela Área de Trabalho de Minutas (ou garanta o link no menu) no eproc 2G.'
    });
  }

  function parseDetalhesPreferenciaAreaMinutasHtml(htmlResp, prefItem, ctxBase, catalogosExtras = {}) {
    const html = htmlResp || '';
    const docResp = new DOMParser().parseFromString(html, 'text/html');
    const baseCat = (ctxBase && (ctxBase.catalogosBasicos || (ctxBase.formInfo && ctxBase.formInfo.catalogosBasicos))) || {};
    const { camposP, agQuery } = obterCamposPersonalizadosMesclados(html);

    const mapaGrupos = mesclarMapasStrings(construirMapaSelectOptions(docResp, 'selFormularioPersonalizacaoGrupo'), baseCat.grupos);
    const meta = extrairMetadadosBasicosPrefViewer(docResp, prefItem, agQuery, camposP, mapaGrupos);

    const mapFrom = (sid) => mesclarMapasStrings(construirMapaSelectOptions(docResp, sid), baseCat[sid]);
    const mapaTipos = mapFrom('selTipoDocumento');
    const mapaStatus = mapFrom('selStatusMinuta');
    const mapaLocs = mesclarMapasStrings(mapFrom('selLocalizador'), mesclarMapasStrings(catalogosExtras.localizadoresExtras, baseCat.localizadores));
    const mapaClasses = mapFrom('selClasseJudicial');
    const mapaComp = mapFrom('selCompetencia');
    const mapaJuizo = mapFrom('selJuizo');
    const mapaSitProc = mapFrom('selStatusProcesso');
    const mapaDadoComp = mapFrom('selDadoComplementar');
    const mapaSigMin = mapFrom('selSigiloMinuta');
    const mapaSigProc = mapFrom('selSigiloProcesso');

    const tiposDocumento = resolverIdsParaTextos(obterSelecaoMultiplaEprocDom(docResp, html, 'selTipoDocumento', camposP), mapaTipos);
    const statusMinuta = resolverIdsParaTextos(obterSelecaoMultiplaEprocDom(docResp, html, 'selStatusMinuta', camposP), mapaStatus);
    const localizadoresFiltro = resolverIdsParaTextos(obterSelecaoMultiplaEprocDom(docResp, html, 'selLocalizador', camposP), mapaLocs);

    const rdOpLoc = docResp.querySelector('input[name="localizadorOperador"][checked], input[name="localizadorOperador"]:checked');
    const opLocCod = String(camposP.localizadorOperador || (rdOpLoc ? rdOpLoc.value : '') || '').trim().toUpperCase();
    const operadorLocalizador = localizadoresFiltro.length > 0 ? (opLocCod === 'OU' ? 'OU' : (opLocCod === 'E' ? 'E' : opLocCod)) : '';

    const lerInputTexto = (id) => {
      if (camposP[id] !== undefined && camposP[id] !== null) return String(camposP[id]).trim();
      const el = docResp.getElementById(id);
      return el ? decodificarEntidadesHtml(decodeEntities(el.value || el.getAttribute('value') || '')).trim() : '';
    };

    const usuariosCriadores = [];
    docResp.querySelectorAll('#selUsuarioCriador option').forEach(opt => {
      const t = decodificarEntidadesHtml(decodeEntities(opt.textContent || '')).trim();
      if (t && opt.value !== 'null') usuariosCriadores.push(t);
    });
    const txtUser = lerInputTexto('txtUsuarioCriador');
    if (txtUser && !normalizar(txtUser).includes('matricula') && !usuariosCriadores.includes(txtUser)) {
      usuariosCriadores.push(txtUser);
    }

    const orgaoProprietario = lerInputTexto('texOrgaoProprietario');
    const termoPesquisa = lerInputTexto('txtTermoPesquisa');
    const descricaoMinuta = lerInputTexto('txtDescricaoMinuta');
    const assinanteIndicado = lerInputTexto('txtAssinanteIndicado');
    const assinante = lerInputTexto('txtAssinante');
    const lembrete = lerInputTexto('txtLembreteMinuta');

    const resolveSingle = (sid, mapa) => {
      const vals = obterValoresSelecionadosSelect(docResp, sid);
      const v = (camposP[sid] !== undefined ? String(camposP[sid]).trim() : '') || (vals[0] || '');
      if (!v || v === 'null') return '';
      return mapa.get(v) || v;
    };

    const sigiloMinuta = resolveSingle('selSigiloMinuta', mapaSigMin);
    const sigiloProcesso = resolveSingle('selSigiloProcesso', mapaSigProc);
    const juizo = resolveSingle('selJuizo', mapaJuizo);
    const statusProcesso = resolveSingle('selStatusProcesso', mapaSitProc);
    const dadoComplementar = resolveSingle('selDadoComplementar', mapaDadoComp);

    const classesJudiciais = resolverIdsParaTextos(obterSelecaoMultiplaEprocDom(docResp, html, 'selClasseJudicial', camposP), mapaClasses);
    const competencias = resolverIdsParaTextos(obterSelecaoMultiplaEprocDom(docResp, html, 'selCompetencia', camposP), mapaComp);

    const classifOut = [];
    const inpClf = docResp.getElementById('selClassificacaoConteudo');
    const rawClf = inpClf ? (inpClf.value || inpClf.getAttribute('value') || '') : '';
    if (rawClf) {
      const mapaClf = new Map(catalogosExtras.classificacoes || []);
      const idsClf = extrairItensSelect2OuIds(rawClf, mapaClf);
      resolverIdsParaTextos(idsClf, mapaClf).forEach(t => { if (!classifOut.includes(t)) classifOut.push(t); });
    }
    docResp.querySelectorAll('#s2id_selClassificacaoConteudo .select2-search-choice div').forEach(el => {
      const t = decodificarEntidadesHtml(decodeEntities(el.textContent || '')).trim();
      if (t && !classifOut.includes(t)) classifOut.push(t);
    });

    const extras = [];
    const chkPrec = docResp.getElementById('chkSinPrecedenteRelevante');
    if ((chkPrec && (chkPrec.checked || chkPrec.hasAttribute('checked'))) || camposP.chkSinPrecedenteRelevante === 'S') {
      extras.push('Precedente relevante');
    }
    const rdBloq = docResp.querySelector('input[name="rdoMinutaBloqueio"][checked], input[name="rdoMinutaBloqueio"]:checked');
    if (rdBloq && rdBloq.value && rdBloq.value !== 'nao_listar_minutas_bloqueadas') {
      extras.push(rdBloq.value === 'listar_somente_minutas_bloqueadas' ? 'Somente bloqueadas' : 'Incluir bloqueadas');
    }
    const dtIni = lerInputTexto('txtDataInicial');
    const dtFim = lerInputTexto('txtDataFinal');
    if (dtIni || dtFim) extras.push(`Período: ${dtIni || '...'} a ${dtFim || '...'}`);
    const codDoc = lerInputTexto('txtCodigoDocumento');
    if (codDoc) extras.push(`Cód. Doc: ${codDoc}`);
    const loteMin = lerInputTexto('txtLoteMinuta');
    if (loteMin) extras.push(`Lote: ${loteMin}`);

    return {
      ...prefItem,
      detalhado: true,
      erroDetalhe: '',
      ...meta,
      tiposDocumento,
      statusMinuta,
      localizadoresFiltro,
      operadorLocalizador,
      usuariosCriadores,
      orgaoProprietario,
      termoPesquisa,
      descricaoMinuta,
      assinanteIndicado,
      assinante,
      lembrete,
      sigiloMinuta,
      classificacao: classifOut,
      classesJudiciais,
      competencias,
      juizo,
      statusProcesso,
      dadoComplementar,
      sigiloProcesso,
      opcoesExtras: extras.join(' | ')
    };
  }

  async function carregarDetalhesPreferenciaAreaMinutas(prefItem, ctx, options = {}) {
    const cacheMap = obterCacheDetalhesModuloViewer('area_minutas');
    if (!options.forcarRecarga && cacheMap.has(prefItem.id)) {
      return cacheMap.get(prefItem.id);
    }

    const htmlResp = await executarPostPreferenciaClassica(prefItem, ctx);
    const preParsed = parseDetalhesPreferenciaAreaMinutasHtml(htmlResp, prefItem, ctx, {});
    const precisaLocExtra = (preParsed.localizadoresFiltro || []).some(v => /^ID:\s*/.test(v));
    const precisaClf = (preParsed.classificacao || []).some(v => /^ID:\s*/.test(v));

    const [localizadoresExtras, classificacoes] = await Promise.all([
      precisaLocExtra ? obterCatalogoLocalizadoresExtraViewer(ctx) : Promise.resolve(null),
      precisaClf ? obterCatalogoClassificacoesViewer(ctx) : Promise.resolve(null)
    ]);

    const detalhado = (precisaLocExtra || precisaClf)
      ? parseDetalhesPreferenciaAreaMinutasHtml(htmlResp, prefItem, ctx, { localizadoresExtras, classificacoes })
      : preParsed;

    cacheMap.set(prefItem.id, detalhado);
    return detalhado;
  }

  // -------------------- MÓDULO 2: RELATÓRIO GERAL --------------------
  async function obterContextoRelatorioVisualizador() {
    let docBase = null;
    let htmlBase = '';
    let baseHref = window.location.href;

    const naTelaRel = (d) => Boolean(d && d.getElementById('frmProcessoLista') && (d.getElementById('selPreferencia') || d.getElementById('selPreferencia-list') || d.getElementById('selLocalizadorPrincipal')));
    if (naTelaRel(document)) {
      docBase = document;
      htmlBase = document.documentElement ? document.documentElement.innerHTML : '';
    } else {
      const urlMenu = obterUrlAcaoMenu('relatorio_geral_listar');
      if (!urlMenu || !/[?&]hash=/i.test(urlMenu)) {
        return {
          disponivel: false,
          motivo: 'Para visualizar as preferências de Relatório Geral, abra a tela Relatório Geral de Processos no eproc 2G.'
        };
      }
      const resp = await fetch(urlMenu, { credentials: 'same-origin' });
      if (!resp.ok) {
        return {
          disponivel: false,
          motivo: `Não foi possível acessar o Relatório Geral em segundo plano (HTTP ${resp.status}). Abra a tela Relatório Geral e tente novamente.`
        };
      }
      htmlBase = await lerRespostaTexto(resp);
      baseHref = urlMenu;
      docBase = new DOMParser().parseFromString(htmlBase, 'text/html');
    }

    const urls = extrairUrlsAjaxTelaEproc(htmlBase, docBase, baseHref, { nomeAcao: 'relatorio_geral_listar' });
    const formInfo = extrairCamposBaseFormEproc(docBase, baseHref, htmlBase, {
      formId: 'frmProcessoLista',
      acaoPattern: 'relatorio_geral_listar',
      selectsExtras: [
        'selStatusProcesso', 'selCompetencia', 'selIdorgaoColegiado', 'selIdOrgaoJuizo',
        'selRitoProcesso', 'selAnexoFisico', 'selIdSigilo', 'selPrazo', 'selDigitosProcesso',
        'selRemessaAtivaOrgaos', 'selMinutasPendenteJuntada', 'selCodTipoDocumento',
        'selOrgaoDestinoRemessaAtiva', 'selPartesSemProcurador', 'selLocalidadeOrigemPolo',
        'selTipoPessoa', 'selPolo', 'selProcuracaoValidacao',
        'compSelSigTipoClassificacaoLaudoPericial', 'selFiltroCdaGrupoStatus', 'selTributoFiscal',
        'selTipoTemasRepetitivos', 'selSituacaoTemasRepetitivos', 'selTipoPesquisaTemasRepetitivos'
      ]
    }) || { actionUrl: baseHref, basePairs: [], catalogosBasicos: {} };

    const inpMig = docBase ? docBase.getElementById('conf_migracao') : null;
    const confMigracao = inpMig ? (inpMig.value || inpMig.getAttribute('value') || '') : '';

    if (!urls.urlListar && !urls.urlUiPrefListar) {
      return {
        disponivel: false,
        motivo: 'Controles de preferências do Relatório Geral (#selPreferencia-list / ui_preferencias) não localizados nesta página.'
      };
    }

    return {
      disponivel: true,
      nomeAcao: 'relatorio_geral_listar',
      docBase,
      htmlBase,
      baseHref,
      formInfo,
      urls,
      confMigracao
    };
  }

  async function obterListaCompletaPreferenciasRelatorios(ctx) {
    const mapaPorId = new Map();
    const normFlag = (v) => {
      if (v === true) return 'Sim';
      if (v === false) return 'Não';
      const semTags = String(v === null || v === undefined ? '' : v).replace(/<[^>]+>/g, ' ').trim();
      const s = normalizar(semTags);
      if (!s) return '';
      return (s === 's' || s === 'sim' || s === '1' || s === 'true') ? 'Sim' : ((s === 'n' || s === 'nao' || s === '0' || s === 'false') ? 'Não' : semTags);
    };
    const registrar = (it) => {
      if (!it || !it.id || !it.nome) return;
      const prev = mapaPorId.get(it.id) || {};
      mapaPorId.set(it.id, {
        id: it.id,
        nome: it.nome || prev.nome || '',
        padrao: it.padrao || prev.padrao || '',
        painelInicial: it.painelInicial || prev.painelInicial || '',
        acaoPreferencial: it.acaoPreferencial || it.painelInicial || prev.acaoPreferencial || prev.painelInicial || '',
        tipo: it.tipo || prev.tipo || '',
        grupo: it.grupo || prev.grupo || '',
        rawObj: it.rawObj || prev.rawObj || null,
        urlEditar: it.urlEditar || prev.urlEditar || ''
      });
    };

    // 1. Tenta listagem oficial via modal_lista_preferencias + DataTables JSON
    const listaModal = await obterListaCompletaPreferenciasMinutas(ctx);
    (listaModal || []).forEach(it => registrar({
      ...it,
      acaoPreferencial: it.acaoPreferencial || it.painelInicial || ''
    }));

    // 2. Complementa com ui_preferencias/listar JSON (caso haja itens fora da primeira fonte)
    const urlUiList = (ctx && ctx.urls && ctx.urls.urlUiPrefListar) || '';
    if (urlUiList) {
      for (const qBody of ['q=', 'value=', 'q=%', 'term=']) {
        try {
          const resp = await fetch(urlUiList, {
            method: 'POST',
            credentials: 'same-origin',
            headers: {
              'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8',
              'X-Requested-With': 'XMLHttpRequest'
            },
            body: qBody
          });
          if (!resp.ok) continue;
          const txt = await lerRespostaTexto(resp);
          const json = JSON.parse(txt);
          const arr = Array.isArray(json) ? json : (json.data || json.itens || json.items || []);
          if (Array.isArray(arr) && arr.length > 0) {
            arr.forEach(p => {
              const id = String(p.IdFormularioPersonalizacao || p.IdPreferencia || p.id || p.value || '').trim();
              const nome = decodificarEntidadesHtml(decodeEntities(String(p.Descricao || p.nome || p.label || '').replace(/<[^>]+>/g, ''))).trim();
              const rawInd = normalizar(String(p.SinPreferenciaIndividual === null || p.SinPreferenciaIndividual === undefined ? '' : p.SinPreferenciaIndividual));
              const tipo = (rawInd === 's' || rawInd === 'sim' || rawInd === 'i' || rawInd === '1' || rawInd === 'true') ? 'Individual' : ((rawInd === 'n' || rawInd === 'nao' || rawInd === 'u' || rawInd === '0' || rawInd === 'false') ? 'Unidade' : '');
              const pain = normFlag(p.SinPainelInicial);
              registrar({
                id,
                nome,
                padrao: normFlag(p.SinValorPadrao),
                painelInicial: pain,
                acaoPreferencial: pain,
                tipo,
                grupo: decodificarEntidadesHtml(decodeEntities(p.DescricaoGrupoFormularioPersonalizacaoGrupo || '')).trim(),
                rawObj: p
              });
            });
            break;
          }
        } catch (eU) {}
      }
    }

    return Array.from(mapaPorId.values());
  }

  async function obterCatalogoLocalizadoresRelatorioViewer(ctx, opcoes = {}) {
    const cache = obterCacheCatalogosMinutaViewer();
    const precisaHtml = Boolean(opcoes.forcarHtmlOrgao);
    if (cache.localizadoresRelatorio && (!precisaHtml || cache.localizadoresRelatorioComHtml)) {
      return cache.localizadoresRelatorio;
    }

    if (cache._promLocalizadoresRelatorio) {
      await cache._promLocalizadoresRelatorio;
      if (cache.localizadoresRelatorio && (!precisaHtml || cache.localizadoresRelatorioComHtml)) {
        return cache.localizadoresRelatorio;
      }
    }

    const limparTxtLoc = (s) => decodificarEntidadesHtml(decodeEntities(String(s || ''))).replace(/\u00a0/g, ' ').replace(/\s+/g, ' ').trim();
    const mesclarRotulo = (mapa, id, rotulo) => {
      const idStr = String(id || '').trim();
      const rot = limparTxtLoc(rotulo);
      if (!idStr || !rot) return;
      const atual = mapa.get(idStr) || '';
      const atualRuim = !atual || /[?\uFFFD]/.test(atual);
      const novoBom = !/[?\uFFFD]/.test(rot);
      if (!atual || (atualRuim && novoBom) || (novoBom && /[^\x00-\x7F]/.test(rot) && !/[^\x00-\x7F]/.test(atual))) {
        mapa.set(idStr, rot);
      }
    };

    const tarefa = (async () => {
      const mapa = cache.localizadoresRelatorio
        ? new Map(cache.localizadoresRelatorio)
        : new Map(ctx && ctx.formInfo && ctx.formInfo.catalogosBasicos ? ctx.formInfo.catalogosBasicos.localizadores : []);

      // 1. Consulta o endpoint JSON de localizadores do Relatório Geral (se ainda não consultado nesta sessão)
      if (!cache._relatorioJsonLocsConsultado) {
        cache._relatorioJsonLocsConsultado = true;
        const urlLoc = (ctx && ctx.urls && ctx.urls.urlListarLocRelatorio) || '';
        if (urlLoc) {
          try {
            const resp = await fetch(urlLoc, {
              method: 'POST',
              credentials: 'same-origin',
              headers: { 'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8' },
              body: 'selIdOrgaoJuizo='
            });
            if (resp.ok) {
              const txt = await lerRespostaTexto(resp);
              let json = null;
              try { json = JSON.parse(txt); } catch (eJ) {}
              if (Array.isArray(json)) {
                json.forEach(c => {
                  const id = String(c.IdLocalizadorOrgao || c.id || '').trim();
                  const sig = limparTxtLoc(c.SigLocalizador || '');
                  const des = limparTxtLoc(c.DesLocalizador || '');
                  const label = (sig && des && sig !== des) ? `${sig} - ${des}` : (sig || des || limparTxtLoc(c.label || c.Descricao || c.descricao || ''));
                  mesclarRotulo(mapa, id, label);
                });
              }
            }
          } catch (e) {}
        }
      }

      // 2. Se faltam localizadores, ou houver '?' / falta de emojis (DB/JSON converte emojis em '?'), consulta localizador_orgao_listar (HTML preserva entidades &#128310;)
      const temInterrogacaoCatalogo = Array.from(mapa.values()).some(v => /[?\uFFFD]/.test(v));
      if (!cache.localizadoresRelatorioComHtml && (precisaHtml || mapa.size === 0 || temInterrogacaoCatalogo)) {
        try {
          if (typeof obterLocalizadoresOrgaoEproc === 'function') {
            const lista = await obterLocalizadoresOrgaoEproc();
            (lista || []).forEach(it => {
              if (!it || !it.id) return;
              const sig = limparTxtLoc(it.nomeCompleto || '');
              const des = limparTxtLoc(it.nomeCurto || '');
              const rot = (sig && des && sig !== des) ? `${sig} - ${des}` : (sig || des);
              mesclarRotulo(mapa, it.id, rot);
            });
            if (lista && lista.length > 0) cache.localizadoresRelatorioComHtml = true;
          } else if (ctx && ctx.urls && ctx.urls.urlLocalizadoresOrgao) {
            const respHtml = await fetch(ctx.urls.urlLocalizadoresOrgao, { credentials: 'same-origin' });
            if (respHtml.ok) {
              const html = await lerRespostaTexto(respHtml);
              const doc = new DOMParser().parseFromString(html, 'text/html');
              let achouHtml = false;
              doc.querySelectorAll('tr').forEach(tr => {
                const mId = (tr.innerHTML || '').match(/id_localizador_orgao=(\d+)/i);
                const tds = tr.querySelectorAll('td');
                if (mId && tds.length >= 3) {
                  const sig = limparTxtLoc(tds[1].textContent || '');
                  const des = limparTxtLoc(tds[2].textContent || '');
                  const rot = (sig && des && sig !== des) ? `${sig} - ${des}` : (sig || des);
                  if (rot) {
                    mesclarRotulo(mapa, mId[1], rot);
                    achouHtml = true;
                  }
                }
              });
              if (achouHtml) cache.localizadoresRelatorioComHtml = true;
            }
          }
        } catch (eHtml) {}
      }

      cache.localizadoresRelatorio = mapa;
      return mapa;
    })();

    cache._promLocalizadoresRelatorio = tarefa;
    try {
      return await tarefa;
    } finally {
      if (cache._promLocalizadoresRelatorio === tarefa) {
        cache._promLocalizadoresRelatorio = null;
      }
    }
  }

  function resolverMascaraInterrogacaoNoCatalogo(textoComInterrogacao, mapaCatalogo) {
    if (!textoComInterrogacao || !mapaCatalogo || mapaCatalogo.size === 0) return '';
    const limpo = String(textoComInterrogacao).trim();
    if (!/[?\uFFFD]/.test(limpo)) return '';
    const partes = limpo.split(/(?:\?+|\uFFFD+)/g);
    const escRegex = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const padrao = '^' + partes.map(escRegex).join('[\\s\\S]{1,8}?') + '$';
    let re = null;
    try { re = new RegExp(padrao, 'i'); } catch (e) { return ''; }

    const candidatos = [];
    const vistos = new Set();
    for (const val of mapaCatalogo.values()) {
      const cand = String(val || '').trim();
      if (!cand || vistos.has(cand) || /[?\uFFFD]/.test(cand)) continue;
      if (re.test(cand)) {
        vistos.add(cand);
        candidatos.push(cand);
        if (candidatos.length > 1) break;
      }
    }
    return candidatos.length === 1 ? candidatos[0] : '';
  }

  function extrairLabelsTagifyRelatorio(rawVal, mapaFallback = null) {
    if (!rawVal) return [];
    const limpar = (s) => decodificarEntidadesHtml(decodeEntities(String(s || '')))
      .replace(/\\+\//g, '/')
      .replace(/\s+/g, ' ')
      .trim();
    const out = [];
    const addLabel = (lbl) => {
      const l = limpar(lbl);
      if (l && !out.includes(l)) out.push(l);
    };
    const resolverComMapa = (idCand, textoCand) => {
      const idStr = String(idCand || '').trim();
      const textoLimpo = limpar(textoCand);
      if (idStr && mapaFallback && mapaFallback.has(idStr)) {
        const doMapa = limpar(mapaFallback.get(idStr));
        if (doMapa && (!textoLimpo || /[?\uFFFD]/.test(textoLimpo) || !/[?\uFFFD]/.test(doMapa))) {
          return doMapa;
        }
      }
      if (textoLimpo && /[?\uFFFD]/.test(textoLimpo) && mapaFallback && mapaFallback.size > 0) {
        const matchUnico = resolverMascaraInterrogacaoNoCatalogo(textoLimpo, mapaFallback);
        if (matchUnico) return matchUnico;
      }
      return textoLimpo || (idStr ? `ID: ${idStr}` : '');
    };

    let parsed = rawVal;
    if (typeof rawVal === 'string') {
      const trimmed = rawVal.trim();
      if (!trimmed || trimmed === '[]') return [];
      const tentarParseJson = (str) => {
        if (!str.startsWith('[') && !str.startsWith('{')) return null;
        try { return JSON.parse(str); } catch (e1) {}
        const semBarra = str.replace(/\\\//g, '/');
        try { return JSON.parse(semBarra); } catch (e2) {}
        try { return JSON.parse(semBarra.replace(/\\"/g, '"')); } catch (e3) { return null; }
      };
      if (trimmed.startsWith('[') || trimmed.startsWith('{')) {
        parsed = tentarParseJson(trimmed);
      }
      if (!parsed || typeof parsed === 'string') {
        addLabel(resolverComMapa('', trimmed));
        return out;
      }
    }

    const itens = Array.isArray(parsed) ? parsed : [parsed];
    itens.forEach(it => {
      if (!it) return;
      if (typeof it === 'string' || typeof it === 'number') {
        addLabel(resolverComMapa(String(it), ''));
        return;
      }
      if (typeof it === 'object') {
        const d = it.data;
        let idCand = '';
        let textoDados = '';
        if (d && typeof d === 'object') {
          idCand = String(d.IdLocalizadorOrgao || d.id || it.key || '').trim();
          if (d.SigLocalizador || d.DesLocalizador) {
            textoDados = [d.SigLocalizador || '', d.DesLocalizador || ''].filter(Boolean).join(' - ');
          } else {
            textoDados = d.Descricao || d.nome || d.label || '';
          }
        } else if (d !== undefined && d !== null && String(d).trim() !== '') {
          idCand = String(d).trim();
        }
        const textoPreferido = it.value || textoDados;
        addLabel(resolverComMapa(idCand, textoPreferido));
      }
    });
    return out;
  }

  function resolverSelectRelatorio(val, mapaSelect) {
    if (val === undefined || val === null || val === '') return [];
    const arr = Array.isArray(val) ? val : [val];
    const out = [];
    arr.forEach(v => {
      const s = String(v || '').trim();
      if (!s || s === 'null') return;
      const lbl = (mapaSelect && mapaSelect.get(s)) || s;
      if (!out.includes(lbl)) out.push(lbl);
    });
    return out;
  }

  function parseDetalhesPreferenciaRelatorioRequest(requestObj, prefItem, ctxBase, mapaLocsFallback = null) {
    const req = (requestObj && typeof requestObj === 'object' && !Array.isArray(requestObj)) ? requestObj : {};
    const baseCat = (ctxBase && ctxBase.formInfo && ctxBase.formInfo.catalogosBasicos) || {};
    const mapaLocs = mesclarMapasStrings(mapaLocsFallback, baseCat.localizadores);

    const localizadoresFiltro = extrairLabelsTagifyRelatorio(req.selLocalizadorPrincipal, mapaLocs);
    if (req.selLocalizadorPrincipal_value && typeof req.selLocalizadorPrincipal_value === 'object') {
      const precisaViaValue = localizadoresFiltro.length === 0 || localizadoresFiltro.some(l => /[?\uFFFD]/.test(l) || /^ID:\s*/.test(l));
      if (precisaViaValue) {
        const locsViaValue = [];
        Object.entries(req.selLocalizadorPrincipal_value).forEach(([kId, v]) => {
          const obj = (v && typeof v === 'object') ? v : {};
          const id = String(obj.IdLocalizadorOrgao || obj.id || kId || '').trim();
          const labelTxt = (obj.SigLocalizador || obj.DesLocalizador)
            ? [obj.SigLocalizador || '', obj.DesLocalizador || ''].filter(Boolean).join(' - ').trim()
            : '';
          const doMapa = (id && mapaLocs.has(id)) ? mapaLocs.get(id) : '';
          let escolhido = '';
          if (doMapa && !/[?\uFFFD]/.test(doMapa)) escolhido = doMapa;
          else if (labelTxt && !/[?\uFFFD]/.test(labelTxt)) escolhido = labelTxt;
          else if (labelTxt && mapaLocs.size > 0) escolhido = resolverMascaraInterrogacaoNoCatalogo(labelTxt, mapaLocs) || doMapa || labelTxt;
          else escolhido = doMapa || labelTxt || (id ? `ID: ${id}` : '');
          const limpo = decodificarEntidadesHtml(decodeEntities(escolhido)).replace(/\s+/g, ' ').trim();
          if (limpo && !locsViaValue.includes(limpo)) locsViaValue.push(limpo);
        });
        if (locsViaValue.length > 0 && (localizadoresFiltro.length === 0 || locsViaValue.some(l => !/[?\uFFFD]/.test(l)))) {
          localizadoresFiltro.length = 0;
          locsViaValue.forEach(l => localizadoresFiltro.push(l));
        }
      }
    }

    const opRaw = String(req.tipoOperacaoLocalizador || '').trim().toUpperCase();
    const operacaoLocalizador = localizadoresFiltro.length > 0 ? (opRaw || 'E') : (opRaw || '');

    const situacaoProcesso = resolverSelectRelatorio(req.selStatusProcesso, baseCat.selStatusProcesso);
    const lembrete = decodificarEntidadesHtml(decodeEntities(String(req.txtLembrete || '').trim()));
    const competencia = resolverSelectRelatorio(req.selCompetencia, baseCat.selCompetencia);
    const orgaoColegiado = resolverSelectRelatorio(req.selIdorgaoColegiado, baseCat.selIdorgaoColegiado);
    const juizo = resolverSelectRelatorio(req.selIdOrgaoJuizo, baseCat.selIdOrgaoJuizo).join('; ');
    const rito = resolverSelectRelatorio(req.selRitoProcesso, baseCat.selRitoProcesso).join('; ');
    const classesJudiciais = [
      ...extrairLabelsTagifyRelatorio(req.selClasse),
      ...extrairLabelsTagifyRelatorio(req.selClasseOrigem)
    ];
    const assuntos = extrairLabelsTagifyRelatorio(req.selAssunto);
    const dadosComplementares = extrairLabelsTagifyRelatorio(req.selDadoComplementar);
    const prazo = resolverSelectRelatorio(req.selPrazo, baseCat.selPrazo).join('; ');

    const diasSit = req.txtDiasSituacao ? `Situação >= ${req.txtDiasSituacao}d` : '';
    const diasSemMov = req.txtDiasSemMovimentacao ? `Sem mov. >= ${req.txtDiasSemMovimentacao}d` : '';
    const diasSituacao = [diasSit, diasSemMov].filter(Boolean).join(' | ');

    const evUlt = extrairLabelsTagifyRelatorio(req.selUltimoEvento);
    const evCom = extrairLabelsTagifyRelatorio(req.selComEvento);
    const evSem = extrairLabelsTagifyRelatorio(req.selSemEvento);
    const evPartes = [
      evUlt.length ? `Último: ${evUlt.join(', ')}` : '',
      evCom.length ? `Com: ${evCom.join(', ')}` : '',
      evSem.length ? `Sem: ${evSem.join(', ')}` : ''
    ].filter(Boolean);
    const eventosFiltro = evPartes.join(' | ');

    const entidades = extrairLabelsTagifyRelatorio(req.selEntidade);
    const sigilo = resolverSelectRelatorio(req.selIdSigilo, baseCat.selIdSigilo).join('; ');

    const chavesPrincipais = new Set([
      'selLocalizadorPrincipal', 'selLocalizadorPrincipal_value', 'tipoOperacaoLocalizador',
      'selStatusProcesso', 'txtLembrete', 'selCompetencia', 'selIdorgaoColegiado',
      'selIdOrgaoJuizo', 'selRitoProcesso', 'selClasse', 'selClasseOrigem', 'selAssunto',
      'selDadoComplementar', 'selPrazo', 'txtDiasSituacao', 'txtDiasSemMovimentacao',
      'selUltimoEvento', 'selComEvento', 'selSemEvento', 'selEntidade', 'selIdSigilo',
      'IdPreferencia', 'conf_migracao', 'hdnInfraTipoPagina'
    ]);
    const extras = [];
    if (req.txtDataAutuacaoInicio || req.txtDataAutuacaoFim) {
      extras.push(`Autuação: ${req.txtDataAutuacaoInicio || '...'} a ${req.txtDataAutuacaoFim || '...'}`);
    }
    const chavesLegiveis = {
      selAnexoFisico: 'Anexo físico',
      selRemessaAtivaOrgaos: 'Remessa ativa',
      selMinutasPendenteJuntada: 'Minutas pend. juntada',
      selCodTipoDocumento: 'Tipo doc. minuta',
      selOrgaoDestinoRemessaAtiva: 'Órgão destino remessa',
      selPartesSemProcurador: 'Partes sem procurador',
      selPolo: 'Polo',
      selTipoPessoa: 'Tipo pessoa',
      selDigitosProcesso: 'Dígitos processo',
      txtApenso: 'Apenso'
    };
    Object.entries(req).forEach(([k, v]) => {
      if (chavesPrincipais.has(k) || k === 'txtDataAutuacaoInicio' || k === 'txtDataAutuacaoFim') return;
      if (k.endsWith('_value') || v === '' || v === null || v === undefined || (Array.isArray(v) && v.length === 0)) return;
      const nomeCampo = Object.prototype.hasOwnProperty.call(chavesLegiveis, k) ? chavesLegiveis[k] : k;
      let valFmt = '';
      if (Object.prototype.hasOwnProperty.call(baseCat, k) && baseCat[k]) valFmt = resolverSelectRelatorio(v, baseCat[k]).join(', ');
      else if (typeof v === 'string' && v.trim().startsWith('[')) valFmt = extrairLabelsTagifyRelatorio(v).join(', ');
      else if (Array.isArray(v)) valFmt = v.join(', ');
      else valFmt = String(v).trim();
      if (valFmt && valFmt !== '[]') extras.push(`${nomeCampo}: ${valFmt}`);
    });

    return {
      ...prefItem,
      detalhado: true,
      erroDetalhe: '',
      localizadoresFiltro,
      operacaoLocalizador,
      situacaoProcesso,
      lembrete,
      competencia,
      orgaoColegiado,
      juizo,
      rito,
      classesJudiciais,
      assuntos,
      dadosComplementares,
      prazo,
      diasSituacao,
      eventosFiltro,
      entidades,
      sigilo,
      opcoesExtras: extras.join(' | ')
    };
  }

  async function carregarDetalhesPreferenciaRelatorio(prefItem, ctx, options = {}) {
    const cacheMap = obterCacheDetalhesModuloViewer('relatorios');
    if (!options.forcarRecarga && cacheMap.has(prefItem.id)) {
      return cacheMap.get(prefItem.id);
    }

    const urlBuscar = ctx && ctx.urls && ctx.urls.urlBuscarRequest;
    if (!urlBuscar) {
      throw new Error('Endpoint ui_preferencias/buscar_request_por_id não localizado.');
    }

    const confMig = ctx.confMigracao
      ? (ctx.confMigracao.includes('&quot;') ? decodeEntities(ctx.confMigracao) : ctx.confMigracao)
      : '';

    const objDataLimpo = {};
    if (prefItem.rawObj && typeof prefItem.rawObj === 'object') {
      Object.entries(prefItem.rawObj).forEach(([k, v]) => {
        if (!k || k.startsWith('col_') || k.startsWith('DT_')) return;
        if (v === null || v === undefined || typeof v === 'string' || typeof v === 'number' || typeof v === 'boolean') {
          objDataLimpo[k] = v;
        }
      });
    }
    if (!objDataLimpo.IdFormularioPersonalizacao) objDataLimpo.IdFormularioPersonalizacao = prefItem.id;
    if (!objDataLimpo.Descricao) objDataLimpo.Descricao = prefItem.nome;

    const estrategias = [
      () => {
        // Formato nativo do Tagify + UI.PHPHelper.autocomplete (#frmPreferencias)
        const sp = new URLSearchParams();
        sp.set('selPreferencia', JSON.stringify([{
          key: 0,
          isObject: false,
          value: String(objDataLimpo.Descricao || prefItem.nome),
          data: objDataLimpo
        }]));
        Object.entries(objDataLimpo).forEach(([k, v]) => {
          sp.set(`selPreferencia_value[${prefItem.id}][${k}]`, v === null || v === undefined ? '' : String(v));
        });
        if (confMig) sp.set('conf_migracao', confMig);
        return sp;
      },
      () => {
        // Tagify com data escalar e chave em array selPreferencia_value[id]
        const sp = new URLSearchParams();
        sp.set('selPreferencia', JSON.stringify([{ value: prefItem.nome, data: prefItem.id }]));
        sp.set(`selPreferencia_value[${prefItem.id}]`, '');
        if (confMig) sp.set('conf_migracao', confMig);
        return sp;
      },
      () => {
        // Tagify apenas (sem selPreferencia_value)
        const sp = new URLSearchParams();
        sp.set('selPreferencia', JSON.stringify([{ value: prefItem.nome, data: prefItem.id }]));
        if (confMig) sp.set('conf_migracao', confMig);
        return sp;
      },
      () => {
        // Fallback escalar direto
        const sp = new URLSearchParams();
        sp.set('selPreferencia', prefItem.id);
        sp.set('IdFormularioPersonalizacao', prefItem.id);
        sp.set('IdPreferencia', prefItem.id);
        if (confMig) sp.set('conf_migracao', confMig);
        return sp;
      }
    ];

    const ordemIndices = [];
    const prefIdx = (typeof ctx._relatorioEstrategiaVencedora === 'number') ? ctx._relatorioEstrategiaVencedora : 0;
    ordemIndices.push(prefIdx);
    for (let i = 0; i < estrategias.length; i++) {
      if (i !== prefIdx) ordemIndices.push(i);
    }

    let reqJson = null;
    let teveRespostaVaziaValida = false;
    let teveErroHttpOuFormato = false;
    let ultimoErro = '';

    for (const idxEst of ordemIndices) {
      try {
        const sp = estrategias[idxEst]();
        const resp = await fetch(urlBuscar, {
          method: 'POST',
          credentials: 'same-origin',
          headers: {
            'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8',
            'X-Requested-With': 'XMLHttpRequest',
            Accept: 'application/json, text/javascript, */*; q=0.01'
          },
          body: sp.toString()
        });
        const txt = await lerRespostaTexto(resp);
        if (!resp.ok) {
          teveErroHttpOuFormato = true;
          const trecho = String(txt || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 120);
          ultimoErro = `HTTP ${resp.status}${trecho ? `: ${trecho}` : ''}`;
          continue;
        }
        let parsed = null;
        try {
          parsed = JSON.parse(txt);
        } catch (eJson) {
          teveErroHttpOuFormato = true;
          const trecho = String(txt || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 120);
          ultimoErro = `Resposta não JSON (${eJson.message || 'parse'})${trecho ? `: ${trecho}` : ''}`;
          continue;
        }

        if (parsed && typeof parsed === 'object' && !Array.isArray(parsed) && Object.keys(parsed).length > 0) {
          reqJson = parsed;
          if (idxEst !== 0 && teveErroHttpOuFormato) {
            ctx._relatorioEstrategiaVencedora = idxEst;
          }
          break;
        }
        teveRespostaVaziaValida = true;
      } catch (eNet) {
        teveErroHttpOuFormato = true;
        ultimoErro = eNet.message || String(eNet);
      }
    }

    if (!reqJson) {
      if (teveRespostaVaziaValida) {
        reqJson = {};
      } else {
        throw new Error(`${ultimoErro || 'Falha ao consultar preferência'} [endpoint: ${urlBuscar}]`);
      }
    }

    let detalhado = parseDetalhesPreferenciaRelatorioRequest(reqJson, prefItem, ctx, null);
    const locsIniciais = detalhado.localizadoresFiltro || [];
    const precisaId = locsIniciais.some(v => /^ID:\s*/.test(v));
    const precisaEmoji = locsIniciais.some(v => /[?\uFFFD]/.test(v));
    if (precisaId || precisaEmoji) {
      const mapaLocsRel = await obterCatalogoLocalizadoresRelatorioViewer(ctx, { forcarHtmlOrgao: precisaEmoji });
      detalhado = parseDetalhesPreferenciaRelatorioRequest(reqJson, prefItem, ctx, mapaLocsRel);
    }

    cacheMap.set(prefItem.id, detalhado);
    return detalhado;
  }

  function resolverTextoCelulaViewer(row, col) {
    const val = row[col.key];
    if (Array.isArray(val)) return val.join('; ');
    return val === null || val === undefined ? '' : String(val);
  }

  function gerarCsvPreferenciasViewer(colunas, linhas) {
    const esc = (txt) => {
      const s = String(txt === null || txt === undefined ? '' : txt).replace(/\r?\n/g, ' ');
      return `"${s.replace(/"/g, '""')}"`;
    };
    const header = colunas.map(c => esc(c.label)).join(';');
    const body = (linhas || []).map((row, idx) => {
      return colunas.map(c => {
        if (c.key === '_indice') return esc(idx + 1);
        return esc(resolverTextoCelulaViewer(row, c));
      }).join(';');
    });
    return '\uFEFF' + [header, ...body].join('\r\n');
  }

